import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const distUrl = new URL('../dist/', import.meta.url);
await mkdir(fileURLToPath(distUrl), { recursive: true });
await writeFile(new URL('package.json', distUrl), '{\n  "type": "commonjs"\n}\n', 'utf8');

export interface AsyncQueue<T> {
  push: (value: T) => void;
  close: () => void;
  iterator: AsyncIterableIterator<T>;
}

export function createAsyncQueue<T>(): AsyncQueue<T> {
  const values: T[] = [];
  const waiters: Array<(result: IteratorResult<T>) => void> = [];
  let closed = false;

  const iterator: AsyncIterableIterator<T> = {
    [Symbol.asyncIterator]() {
      return this;
    },
    next() {
      if (values.length > 0) {
        return Promise.resolve({ done: false, value: values.shift()! });
      }
      if (closed) {
        return Promise.resolve({ done: true, value: undefined as never });
      }
      return new Promise<IteratorResult<T>>((resolve) => {
        waiters.push(resolve);
      });
    },
  };

  return {
    iterator,
    push(value) {
      if (closed) return;
      const waiter = waiters.shift();
      if (waiter) {
        waiter({ done: false, value });
        return;
      }
      values.push(value);
    },
    close() {
      if (closed) return;
      closed = true;
      while (waiters.length > 0) {
        waiters.shift()!({ done: true, value: undefined as never });
      }
    },
  };
}

import { getHarness } from './harnesses/index.ts';
import type {
  BuildOptions,
  CommandSpec,
  HarnessConfig,
  HarnessName,
  McpEncoding,
} from './types.ts';

/**
 * Build a CLI command from harness name + options.
 *
 * This is the primary entry point for both library and CLI usage.
 * All CLI syntax knowledge lives in the harness configs — this function
 * just reads config fields and appends the appropriate flags.
 *
 * It does NOT handle:
 * - Output parsing (project-specific)
 * - Process lifecycle (project-specific)
 * - Streaming/format flags (caller appends via extraArgs)
 */
export function buildCommand(
  harness: HarnessName | string,
  options: BuildOptions = {}
): CommandSpec {
  const config = getHarness(harness);
  return buildFromConfig(config, options);
}

/**
 * Single handler: config data → CommandSpec.
 *
 * No structural branching — config fields drive everything.
 * The switch on promptVia is algorithmic (reading a field value
 * on an already-selected config), not structural (asking "what kind
 * of harness is this?").
 *
 * Flag ordering:
 *   binary → baseCmd → sessionResume (if resuming)
 *   → bypassFlags → cwdFlag (if NOT resuming) → modelFlags
 *   → sessionCreate (if NOT resuming) → harness extraArgs
 *   → caller extraArgs → MCP args → prompt argument or stdin marker
 *
 * This ordering handles Codex resume naturally:
 *   codex exec resume <id> [flags...] -
 * And suppresses cwdFlag on resume (session already has a cwd).
 */
function buildFromConfig(config: HarnessConfig, options: BuildOptions): CommandSpec {
  const argv: string[] = [config.binary];
  const forking = options.fork === true && !!options.sessionId;
  const resuming = !forking && options.resume === true && !!options.sessionId;

  // Subcommand (e.g. 'exec' for codex)
  argv.push(...config.baseCmd);

  // Session fork/resume args go right after baseCmd.
  // Fork takes precedence — when native fork is unsupported, the caller is
  // expected to emulate with cp+resume before invoking buildCommand, so a
  // `fork: true` request on a non-fork-capable harness is an error.
  if (forking) {
    if (!config.sessionForkFlags) {
      throw new Error(
        `Harness "${config.binary}" does not natively support fork. Emulate via copy-and-resume (copy the on-disk session file to a new id, then buildCommand with { resume: true, sessionId: <copy> }).`
      );
    }
    argv.push(...config.sessionForkFlags(options.sessionId!));
  } else if (resuming && config.sessionResumeFlags) {
    argv.push(...config.sessionResumeFlags(options.sessionId!));
  }

  // Permissions bypass
  if (options.bypassPermissions) {
    argv.push(...config.bypassFlags);
  }

  // Working directory via CLI flag (only on first turn, not resume)
  if (!resuming && !forking && config.cwdFlag && options.cwd) {
    argv.push(config.cwdFlag, options.cwd);
  }

  // Model flags
  //
  // decomposeModel may already handle reasoning (e.g. codex composite IDs
  // like 'gpt-5.3-codex-high' decompose into -m + -c model_reasoning_effort=high).
  // Track whether decomposition produced effort flags so we don't double-add.
  let modelHandledReasoning = false;
  if (options.model) {
    if (config.decomposeModel) {
      const flags = config.decomposeModel(options.model);
      argv.push(...flags);
      // If decomposition produced -c flags, reasoning is already handled
      modelHandledReasoning = flags.some((f) => f.startsWith('model_reasoning_effort='));
    } else {
      argv.push(config.modelFlag, options.model);
    }
  }

  // Standalone reasoning parameter (oompa passes reasoning separately).
  // Only applied if decomposeModel didn't already handle it.
  if (options.reasoning && !modelHandledReasoning && config.reasoningFlags) {
    argv.push(...config.reasoningFlags(options.reasoning));
  }

  // Session create flags (only when NOT resuming)
  if (!resuming && !forking && options.sessionId && config.sessionCreateFlags) {
    argv.push(...config.sessionCreateFlags(options.sessionId));
  }

  // Extra args from harness config
  if (config.extraArgs && config.extraArgs.length > 0) {
    argv.push(...config.extraArgs);
  }

  // Extra args from caller (project-specific flags)
  if (options.extraArgs && options.extraArgs.length > 0) {
    argv.push(...options.extraArgs);
  }

  // MCP encoding belongs to the harness because some CLIs take argv while
  // others (notably OpenCode) take process environment. Keep it immediately
  // before prompt delivery so positional prompts remain last.
  let mcpEncoding: McpEncoding | undefined;
  if (options.mcpServers && Object.keys(options.mcpServers).length > 0) {
    const requiredServers = Object.entries(options.mcpServers)
      .filter(([, spec]) => spec.required)
      .map(([name]) => name);
    if (requiredServers.length > 0 && config.mcpCapability !== 'required') {
      throw new Error(
        `Harness "${config.binary}" cannot guarantee required MCP server(s): ${requiredServers.join(', ')}`
      );
    }
    if (config.mcp) {
      mcpEncoding = config.mcp(options.mcpServers);
    } else {
      if (requiredServers.length > 0) {
        throw new Error(
          `Harness "${config.binary}" cannot encode required MCP server(s): ${requiredServers.join(', ')}`
        );
      }
    }
  }
  if (mcpEncoding?.args && mcpEncoding.args.length > 0) {
    argv.push(...mcpEncoding.args);
  }

  // Prompt delivery
  //
  // If the harness expects the prompt via stdin, append only its optional
  // stdin marker. process-runner writes spec.prompt after spawn, keeping large
  // prompts out of the operating system's argv size limit.
  if (options.prompt && config.stdin === 'prompt') {
    if (config.stdinPromptArg) argv.push(config.stdinPromptArg);
  } else if (options.prompt) {
    switch (config.promptVia) {
      case 'flag':
        argv.push(config.promptFlag!, options.prompt);
        break;
      case 'cli-arg':
        argv.push(options.prompt);
        break;
      case 'cli-sep':
        argv.push(config.promptSep!, options.prompt);
        break;
      case 'stdin':
        throw new Error('Harness prompt delivery is stdin but stdin behavior is not prompt');
    }
  }

  return {
    argv,
    stdin: config.stdin,
    stdout: config.stdout,
    prompt: options.prompt,
    ...(mcpEncoding?.env && Object.keys(mcpEncoding.env).length > 0
      ? { env: mcpEncoding.env }
      : {}),
  };
}

import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Shared provider/model registry loader.
 *
 * Single source of truth: `catalog.jsonc` at repo root.
 * Both agent-cli-tool and unleashd (via vendor/agent-cli-tool/catalog.jsonc) load this file.
 * Harness argv logic (harnesses/*) stays separate — this file only owns *what* models exist.
 */

function stripJsonc(text: string): string {
  return text.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');
}

export interface CatalogReasoning {
  levels: string[];
  defaultEffort?: string;
}

export interface CatalogModel {
  id: string;
  displayName: string;
  isDefault: boolean;
  reasoning?: CatalogReasoning;
}

export interface CatalogProvider {
  id: string;
  displayName: string;
  shortName: string;
  defaultModelId: string;
  supportsDynamicModels: boolean;
  models: CatalogModel[];
}

export interface Catalog {
  revision: string;
  providers: CatalogProvider[];
}

// stripJsonc is imported from shared/src/utils/jsonc.ts — see comment above.

function findCatalogPath(): string {
  const candidates: string[] = [];

  // CJS: __dirname -> .../src or .../dist
  try {
    // @ts-ignore - __dirname exists in CJS builds
    if (typeof __dirname !== 'undefined') {
      const dir = __dirname as string;
      candidates.push(join(dir, '../catalog.jsonc'));
      candidates.push(join(dir, '../../catalog.jsonc'));
      candidates.push(join(dir, 'catalog.jsonc'));
      candidates.push(join(dir, '../src/catalog.jsonc'));
    }
  } catch {
    // ignore
  }

  // cwd fallbacks (when running via tsx from repo root)
  candidates.push(join(process.cwd(), 'catalog.jsonc'));
  candidates.push(join(process.cwd(), 'vendor/agent-cli-tool/catalog.jsonc'));
  candidates.push(join(process.cwd(), '../agent-cli-tool/catalog.jsonc'));

  for (const p of candidates) {
    if (existsSync(p)) return p;
  }
  throw new Error(`catalog.jsonc not found. Tried:\n${candidates.join('\n')}`);
}

let cached: Catalog | null = null;

export function loadCatalog(): Catalog {
  if (cached) return cached;
  const path = findCatalogPath();
  const raw = readFileSync(path, 'utf-8');
  const json = stripJsonc(raw);
  const parsed = JSON.parse(json) as Catalog;
  // Minimal validation: ensure revision and providers exist
  if (!parsed.revision || !Array.isArray(parsed.providers)) {
    throw new Error(`Invalid catalog at ${path}: missing revision/providers`);
  }
  cached = parsed;
  return cached;
}

export function getProvider(providerId: string): CatalogProvider | undefined {
  return loadCatalog().providers.find((p) => p.id === providerId);
}

export function listModels(providerId: string): CatalogModel[] {
  return getProvider(providerId)?.models ?? [];
}

export function isModelInCatalog(providerId: string, modelId: string): boolean {
  return listModels(providerId).some((m) => m.id === modelId);
}

#!/usr/bin/env node

import { readFileSync } from 'node:fs';
import { buildCommand } from './build.ts';
import { canonicalizeHarness, getHarness, listHarnesses } from './harnesses/index.ts';
import { resolveBinary } from './resolve.ts';
import {
  type ClaudeReasoningLevel,
  type CodexReasoningLevel,
  type MuseReasoningLevel,
  type ExecuteCommandRequest,
  executeCommand,
} from './run.ts';
import type { BuildOptions, HarnessName } from './types.ts';

const USAGE = `agent-cli — Shared CLI agent invocation tool

Usage:
  agent-cli run --harness <name> [options]      Run an agent CLI (primary interface)
  agent-cli build --harness <name> [options]    Build a command (JSON to stdout, for debugging)
  agent-cli check <harness>                     Check if a harness binary is available
  agent-cli list                                List available harnesses
  agent-cli info <harness>                      Show harness details

Options:
  --harness <name>         Agent CLI to invoke (claude, codex, opencode, gemini, cursor, muse, gemini1, gemini2, gemini3)
  --model <id>             Model identifier (harness-specific)
  --prompt <text>          Prompt text
  --session <id>           Session ID (for create or resume)
  --resume                 Resume an existing session (vs create new)
  --cwd <path>             Working directory for the agent process
  --bypass-permissions     Include permissions bypass flags
  --debug-events           Mirror raw provider stdout/stderr to stderr during run
  --reasoning <level>      Reasoning effort level. codex: minimal|low|medium|high|xhigh|max|ultra. claude: low|medium|high|xhigh|max. muse: none|minimal|low|medium|high|xhigh|ultra.
  --resolve                Resolve binary in argv[0] to absolute path (build only)
  --input <json|->         JSON input (inline or stdin). Shape: { harness, model?, prompt?, ... }
  --extra <args...>        Extra args appended after all generated args (must be last)`;

function parseArgs(args: string[]): Record<string, string | boolean | string[]> {
  const result: Record<string, string | boolean | string[]> = {};
  let i = 0;
  while (i < args.length) {
    const arg = args[i];
    if (arg === '--extra') {
      result.extra = args.slice(i + 1);
      break;
    }
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const next = args[i + 1];
      if (!next || next.startsWith('--')) {
        result[key] = true;
        i++;
      } else {
        result[key] = next;
        i += 2;
      }
    } else {
      result._positional = arg;
      i++;
    }
  }
  return result;
}

/**
 * Parse build options from CLI flags or JSON input.
 *
 * Two modes:
 * 1. Flag mode: --harness claude --model opus --prompt "hi" ...
 * 2. JSON mode: --input '{"harness":"claude","model":"opus"}' or --input - (stdin)
 *
 * JSON shape matches BuildOptions + { harness: string } at top level.
 */
function parseBuildOptions(rest: string[]): {
  harness: string;
  options: BuildOptions;
  resolve: boolean;
} {
  const opts = parseArgs(rest);

  // JSON input mode: --input '{"harness":...}' or --input - (stdin)
  if (opts.input !== undefined) {
    const raw =
      opts.input === '-'
        ? readFileSync(0, 'utf-8') // fd 0 = stdin
        : (opts.input as string);

    const json = JSON.parse(raw);
    const harness = json.harness as string;
    if (!harness) {
      console.error('Error: JSON input must include "harness" field\n');
      process.exit(1);
    }

    return {
      harness,
      options: {
        model: json.model,
        prompt: json.prompt,
        sessionId: json.sessionId,
        resume: json.resume === true,
        cwd: json.cwd,
        bypassPermissions: json.bypassPermissions === true,
        reasoning: json.reasoning,
        extraArgs: json.extraArgs,
      },
      resolve: opts.resolve === true,
    };
  }

  // Flag mode (original behavior)
  const harness = opts.harness as string | undefined;
  if (!harness) {
    console.error('Error: --harness is required (or use --input for JSON mode)\n');
    console.error(USAGE);
    process.exit(1);
  }
  return {
    harness,
    options: {
      model: opts.model as string | undefined,
      prompt: opts.prompt as string | undefined,
      sessionId: opts.session as string | undefined,
      resume: opts.resume === true,
      cwd: opts.cwd as string | undefined,
      bypassPermissions: opts['bypass-permissions'] === true,
      reasoning: opts.reasoning as string | undefined,
      extraArgs: opts.extra as string[] | undefined,
    },
    resolve: opts.resolve === true,
  };
}

function parseRunRequest(rest: string[]): ExecuteCommandRequest {
  const opts = parseArgs(rest);
  const debugRawEvents =
    opts['debug-events'] === true || process.env.AGENT_CLI_DEBUG_EVENTS === '1';

  if (opts.input !== undefined) {
    const raw = opts.input === '-' ? readFileSync(0, 'utf-8') : (opts.input as string);
    const parsed = JSON.parse(raw) as ExecuteCommandRequest;
    return debugRawEvents ? { ...parsed, debugRawEvents: true } : parsed;
  }

  const harness = opts.harness as string | undefined;
  if (!harness) {
    console.error('Error: --harness is required (or use --input for JSON mode)\n');
    console.error(USAGE);
    process.exit(1);
  }

  const harnessName = harness as HarnessName;
  const base = {
    harness: harnessName,
    mode: 'conversation' as const,
    prompt: (opts.prompt as string | undefined) ?? '',
    cwd: (opts.cwd as string | undefined) ?? process.cwd(),
    model: opts.model as string | undefined,
    extraArgs: opts.extra as string[] | undefined,
    yolo: opts['bypass-permissions'] === true,
    ...(debugRawEvents ? { debugRawEvents: true } : {}),
    ...(opts.session ? { sessionId: opts.session as string } : {}),
    ...(opts.resume && opts.session ? { resumeSessionId: opts.session as string } : {}),
  };

  const canonical = canonicalizeHarness(harnessName);
  if (canonical === 'codex') {
    return {
      ...base,
      harness: 'codex',
      ...(opts.reasoning ? { reasoningEffort: opts.reasoning as CodexReasoningLevel } : {}),
    };
  }
  if (canonical === 'claude') {
    return {
      ...base,
      harness: 'claude',
      ...(opts.reasoning ? { reasoningEffort: opts.reasoning as ClaudeReasoningLevel } : {}),
    };
  }
  if (canonical === 'muse') {
    return {
      ...base,
      harness: 'muse',
      ...(opts.reasoning ? { reasoningEffort: opts.reasoning as MuseReasoningLevel } : {}),
    };
  }

  return base as ExecuteCommandRequest;
}

function exitCodeForReason(reason: string, childExitCode: number | null): number {
  switch (reason) {
    case 'success':
      return childExitCode ?? 0;
    case 'out_of_tokens':
      return 2;
    case 'error':
      return 3;
    case 'killed':
      return 130;
    default:
      return childExitCode ?? 1;
  }
}

async function main(): Promise<void> {
  const [command, ...rest] = process.argv.slice(2);

  if (!command || command === '--help' || command === '-h') {
    console.error(USAGE);
    process.exit(command ? 0 : 1);
  }

  switch (command) {
    case 'run': {
      const request = parseRunRequest(rest);
      const handle = executeCommand(request);

      // Stdin EOF lifecycle: when our parent dies (for any reason, including
      // SIGKILL), the kernel closes its FDs and our stdin gets EOF. Treat
      // this as "parent is gone" and kill the entire child process group.
      // Only active in piped mode — interactive TTY use is unaffected.
      if (!process.stdin.isTTY) {
        process.stdin.on('end', () => {
          const pid = handle.child.pid;
          if (pid != null && handle.child.exitCode === null) {
            try {
              process.kill(-pid, 'SIGTERM');
            } catch {}
            setTimeout(() => {
              try {
                process.kill(-pid, 'SIGKILL');
              } catch {}
            }, 3000);
          }
        });
        process.stdin.resume();
      }

      for await (const event of handle.events) {
        process.stdout.write(`${JSON.stringify(event)}\n`);
      }

      const completion = await handle.completed;
      process.exit(exitCodeForReason(completion.reason, completion.exitCode));
      break;
    }

    case 'build': {
      const { harness, options, resolve } = parseBuildOptions(rest);
      const spec = buildCommand(harness, options);

      // --resolve: replace bare binary name with absolute path
      if (resolve && spec.argv.length > 0) {
        spec.argv[0] = resolveBinary(spec.argv[0]);
      }

      console.log(JSON.stringify(spec));
      break;
    }

    case 'check': {
      const name = rest[0];
      if (!name) {
        console.error('Error: harness name required');
        process.exit(1);
      }
      const config = getHarness(name);
      try {
        const path = resolveBinary(config.binary);
        console.log(JSON.stringify({ available: true, binary: config.binary, path }));
      } catch {
        console.log(JSON.stringify({ available: false, binary: config.binary, path: null }));
      }
      break;
    }

    case 'list': {
      console.log(JSON.stringify(listHarnesses()));
      break;
    }

    case 'info': {
      const name = rest[0];
      if (!name) {
        console.error('Error: harness name required');
        process.exit(1);
      }
      const config = getHarness(name);
      console.log(
        JSON.stringify(
          {
            binary: config.binary,
            baseCmd: config.baseCmd,
            modelFlag: config.modelFlag,
            promptVia: config.promptVia,
            stdin: config.stdin,
            cwdFlag: config.cwdFlag ?? null,
            bypassFlags: config.bypassFlags,
          },
          null,
          2
        )
      );
      break;
    }

    default: {
      console.error(`Unknown command: ${command}\n`);
      console.error(USAGE);
      process.exit(1);
    }
  }
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : String(err));
  process.exit(1);
});

function readPositiveIntEnv(name: string, fallback: number): number {
  const raw = process.env[name];
  if (!raw) return fallback;
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
  return parsed;
}

export const HEARTBEAT_CHECK_INTERVAL_MS = readPositiveIntEnv(
  'AGENT_CLI_HEARTBEAT_CHECK_INTERVAL_MS',
  30_000
);
export const HEARTBEAT_SILENCE_THRESHOLD_MS = readPositiveIntEnv(
  'AGENT_CLI_HEARTBEAT_SILENCE_THRESHOLD_MS',
  25_000
);

import type { CompletionReason, UnifiedAgentEvent } from './runtime-types.ts';

const OUT_OF_TOKENS_PATTERN =
  /out of tokens|token limit|usage limit|insufficient (?:credits|balance)|exceeded(?: your)?(?: current)? quota|credit balance|rate limit exceeded/i;
// biome-ignore lint/suspicious/noControlCharactersInRegex: ANSI stripping intentionally matches ESC and CSI control bytes.
const ANSI_RE = /[\u001b\u009b][\[()#;?]*(?:[0-9]{1,4}(?:;[0-9]{0,4})*)?[0-9A-ORZcf-nqry=><]/g;

export function classifyError(message: string): {
  kind: 'out_of_tokens' | 'error';
  message: string;
} {
  const trimmed = message.trim();
  if (!trimmed) return { kind: 'error', message: 'Unknown error' };
  if (!OUT_OF_TOKENS_PATTERN.test(trimmed)) return { kind: 'error', message: trimmed };
  return {
    kind: 'out_of_tokens',
    message: /^out of tokens:/i.test(trimmed) ? trimmed : `Out of tokens: ${trimmed}`,
  };
}

export function failureEvents(message: string, complete = true): UnifiedAgentEvent[] {
  const classified = classifyError(message);
  const reason: CompletionReason = classified.kind === 'out_of_tokens' ? 'out_of_tokens' : 'error';
  const first: UnifiedAgentEvent =
    classified.kind === 'out_of_tokens'
      ? { type: 'out_of_tokens', message: classified.message }
      : { type: 'error', message: classified.message };
  return complete ? [first, { type: 'turn.complete', reason }] : [first];
}

export function stripAnsi(text: string): string {
  return text.replace(ANSI_RE, '');
}

export function looksLikeInteractiveAuthPrompt(text: string): boolean {
  const normalized = stripAnsi(text).toLowerCase();
  return (
    normalized.includes('opening authentication page in your browser') ||
    normalized.includes('open authentication page in your browser') ||
    normalized.includes('sign in with your browser') ||
    normalized.includes('login with your browser') ||
    normalized.includes('authenticate in your browser') ||
    normalized.includes('press any key to sign in')
  );
}

export function summarizeRawStdout(harness: string, text: string): string {
  const snippet = text.replace(/\s+/g, ' ').trim().slice(0, 240);
  if (looksLikeInteractiveAuthPrompt(text)) {
    return `AUTH_REQUIRED: ${harness} requested interactive authentication. Authenticate that harness outside oompa first. Raw stdout: ${snippet}`;
  }
  return `${harness} emitted non-JSON stdout in conversation mode: ${snippet}`;
}

export function mirrorDebugLines(prefix: string, text: string, trailing: string): string {
  const lines = (trailing + text).split('\n');
  const nextTrailing = lines.pop() ?? '';
  for (const line of lines) {
    process.stderr.write(`${prefix}${line.replace(/\r$/, '')}\n`);
  }
  return nextTrailing;
}

export function flushDebugTrailing(prefix: string, trailing: string): void {
  if (trailing.length > 0) {
    process.stderr.write(`${prefix}${trailing.replace(/\r$/, '')}\n`);
  }
}

import { createAsyncQueue } from './async-queue.ts';
import {
  flushDebugTrailing,
  looksLikeInteractiveAuthPrompt,
  mirrorDebugLines,
  stripAnsi,
  summarizeRawStdout,
} from './diagnostics.ts';
import { canonicalizeHarness } from './harnesses/index.ts';
import { createHeartbeat } from './heartbeat.ts';
