type Emit = (event: UnifiedAgentEvent) => void;

function createStdoutProcessor(
  request: ExecuteCommandRequest,
  parse: HarnessParser,
  emit: Emit,
  updateSession: (json: unknown) => void,
  markStdout: () => void
) {
  let stdoutBuffer = '';
  let bufferedRawStdoutLines: string[] = [];
  let sawParsedStdoutJson = false;
  let authErrorEmitted = false;
  const rawPrefix = `[agent-cli raw ${request.harness} stdout] `;

  const emitRawError = (text: string): void => {
    emit({ type: 'error', message: summarizeRawStdout(request.harness, text) });
  };

  const bufferRawLine = (line: string): void => {
    const nextBuffered = [...bufferedRawStdoutLines, line].slice(-20);
    const combined = nextBuffered.join('\n');
    if (looksLikeInteractiveAuthPrompt(combined)) {
      if (!authErrorEmitted) emitRawError(combined);
      authErrorEmitted = true;
      bufferedRawStdoutLines = [];
      return;
    }
    if (!sawParsedStdoutJson) {
      bufferedRawStdoutLines = nextBuffered;
      return;
    }
    emitRawError(line);
  };

  const processJsonLine = (line: string): void => {
    const trimmed = line.trim();
    if (!trimmed) return;
    const cleaned = stripAnsi(trimmed).trim();
    if (!cleaned) return;
    let json: unknown;
    try {
      json = JSON.parse(cleaned) as unknown;
    } catch {
      bufferRawLine(trimmed);
      return;
    }
    sawParsedStdoutJson = true;
    bufferedRawStdoutLines = [];
    updateSession(json);
    for (const event of parse(json)) emit(event);
  };

  return {
    onChunk(chunk: Buffer): void {
      markStdout();
      const text = chunk.toString();
      if (request.mode === 'single-shot') {
        if (request.debugRawEvents && text.length > 0) {
          process.stderr.write(`${rawPrefix}${text}`);
          if (!text.endsWith('\n')) process.stderr.write('\n');
        }
        if (text.length > 0) emit({ type: 'text.delta', text });
        return;
      }

      stdoutBuffer += text;
      const lines = stdoutBuffer.split('\n');
      stdoutBuffer = lines.pop() ?? '';
      if (request.debugRawEvents) {
        for (const line of lines) process.stderr.write(`${rawPrefix}${line.replace(/\r$/, '')}\n`);
      }
      for (const line of lines) processJsonLine(line);
    },
    flush(): void {
      if (request.mode !== 'conversation') return;
      const trailing = stdoutBuffer.trim();
      if (trailing) {
        if (request.debugRawEvents)
          process.stderr.write(`${rawPrefix}${trailing.replace(/\r$/, '')}\n`);
        processJsonLine(trailing);
      }
      if (bufferedRawStdoutLines.length > 0 && !authErrorEmitted) {
        emitRawError(bufferedRawStdoutLines.join('\n'));
        bufferedRawStdoutLines = [];
      }
    },
  };
}

function createStderrProcessor(request: ExecuteCommandRequest, emit: Emit) {
  let stderrBuffer = '';
  let debugTrailing = '';
  const rawPrefix = `[agent-cli raw ${request.harness} stderr] `;

  return {
    onChunk(chunk: Buffer): void {
      const text = chunk.toString();
      if (request.debugRawEvents) {
        debugTrailing = mirrorDebugLines(rawPrefix, text, debugTrailing);
      }
      stderrBuffer += text;
      emit({ type: 'stderr', text });
    },
    flush(): void {
      if (request.debugRawEvents) flushDebugTrailing(rawPrefix, debugTrailing);
    },
    buffer(): string {
      return stderrBuffer;
    },
  };
}

function silentExitError(
  request: ExecuteCommandRequest,
  exitCode: number | null,
  sawMeaningfulContent: boolean,
  stderrBuffer: string
): string {
  const parts: string[] = [];
  if (exitCode !== null && exitCode !== 0) parts.push(`exit=${exitCode}`);
  if (!sawMeaningfulContent) parts.push('no content ever received');
  const stderr = stderrBuffer.trim();
  if (stderr) parts.push(stderr.split('\n').pop()!);
  const details = parts.length > 0 ? ` (${parts.join('; ')})` : '';
  return `${request.harness} exited without a terminal turn.complete event${details}`;
}

export function executeCommand(request: ExecuteCommandRequest): ExecuteCommandHandle {
  const queue = createAsyncQueue<UnifiedAgentEvent>();
  const canonicalHarness = canonicalizeHarness(request.harness);
  const yolo = request.yolo !== false;
  const codexFullAuto =
    canonicalHarness === 'codex' && 'fullAuto' in request && request.fullAuto === true;
  const bypassPermissions = yolo && !(canonicalHarness === 'codex' && codexFullAuto);
  const session = prepareSession(request);
  const parse = createParser(canonicalHarness);

  let resolvedSessionId = session.resolvedSessionId;
  let completionReason: CompletionReason = 'success';
  let completeEventSeen = false;
  let turnStartedSeen = false;
  let stopRequested = false;
  let stdoutStreamState: StdoutStreamState | null = null;
  let nativeProgressProbe =
    canonicalHarness === 'codex' && resolvedSessionId
      ? createCodexNativeProgressProbe(resolvedSessionId)
      : null;

  let resolveSessionId!: (value: string) => void;
  const sessionId = new Promise<string>((resolve) => {
    resolveSessionId = resolve;
  });

  const heartbeat = createHeartbeat(request.mode === 'conversation', (event) => emit(event), {
    nativeProgress: () => nativeProgressProbe?.poll() ?? null,
    stdoutState: () => stdoutStreamState,
  });

  const emit = (event: UnifiedAgentEvent): void => {
    if (event.type === 'turn.started') {
      if (turnStartedSeen) return;
      turnStartedSeen = true;
    } else if (event.type === 'turn.complete') {
      if (completeEventSeen) return;
      completeEventSeen = true;
      completionReason = event.reason;
    } else if (event.type === 'out_of_tokens') {
      completionReason = 'out_of_tokens';
    } else if (event.type === 'error' && completionReason === 'success') {
      completionReason = 'error';
    }
    if (event.type === 'text.delta' || event.type === 'tool.use') {
      heartbeat.markMeaningful();
    }
    if (!(event.type === 'progress' && event.source === 'agent-cli.heartbeat')) {
      heartbeat.markUnifiedEvent();
    }
    queue.push(event);
  };

  const updateSession = (json: unknown): void => {
    const captured = captureSessionIdFromJson(canonicalHarness, json);
    if (captured && captured !== resolvedSessionId) {
      resolvedSessionId = captured;
      if (canonicalHarness === 'codex') {
        nativeProgressProbe = createCodexNativeProgressProbe(captured);
      }
      emit({ type: 'session.started', sessionId: captured });
    }
  };

  const reasoningEffort = 'reasoningEffort' in request ? request.reasoningEffort : undefined;
  const buildOptions: BuildOptions = {
    model: request.model,
    prompt: request.prompt,
    sessionId: session.buildSessionId,
    resume: session.resume,
    fork: session.fork,
    cwd: request.cwd,
    bypassPermissions,
    mcpServers: request.mcpServers,
    extraArgs: [
      ...buildModeExtraArgs(canonicalHarness, request.mode, yolo, request.cwd, codexFullAuto),
      ...(request.extraArgs ?? []),
    ],
    ...(reasoningEffort && (canonicalHarness === 'codex' || canonicalHarness === 'claude' || canonicalHarness === 'muse')
      ? { reasoning: reasoningEffort }
      : {}),
  };

  const stdout = createStdoutProcessor(request, parse, emit, updateSession, () =>
    heartbeat.markStdout()
  );
  const stderr = createStderrProcessor(request, emit);
  const { child, spec, done } = runCommand(request.harness, {
    ...buildOptions,
    detached: request.detached === true,
    onStdout: (chunk) => stdout.onChunk(chunk),
    onStderr: (chunk) => stderr.onChunk(chunk),
    onStdoutState: (state) => {
      stdoutStreamState = state;
    },
  });

  heartbeat.start();
  if (resolvedSessionId) emit({ type: 'session.started', sessionId: resolvedSessionId });
  emit({ type: 'turn.started' });

  const completed = done
    .then(({ exitCode, signal, spec: doneSpec }) => {
      heartbeat.stop();
      stdout.flush();
      stderr.flush();

      let finalReason = completionReason;
      if (!completeEventSeen) {
        if (stopRequested || exitCode === null) {
          finalReason = 'killed';
        } else if (completionReason !== 'success') {
          finalReason = completionReason;
        } else if (request.mode === 'conversation') {
          finalReason = 'error';
          emit({
            type: 'error',
            message: silentExitError(
              request,
              exitCode,
              heartbeat.sawMeaningfulContent(),
              stderr.buffer()
            ),
          });
        } else {
          finalReason = exitCode === 0 ? 'success' : 'error';
        }
        emit({ type: 'turn.complete', reason: finalReason });
      }

      queue.close();
      resolveSessionId(resolvedSessionId);
      return {
        reason: finalReason,
        exitCode,
        signal,
        sessionId: resolvedSessionId,
        spec: doneSpec,
      };
    })
    .catch((err) => {
      heartbeat.stop();
      emit({
        type: 'error',
        message: `Process failed: ${err instanceof Error ? err.message : String(err)}`,
      });
      emit({ type: 'turn.complete', reason: stopRequested ? 'killed' : 'error' });
      queue.close();
      resolveSessionId(resolvedSessionId);
      throw err;
    });

  return {
    child,
    spec,
    events: queue.iterator,
    sessionId,
    completed,
    stop: (signal?: NodeJS.Signals) => {
      stopRequested = true;
      heartbeat.stop();
      if (child.exitCode === null) {
        if (request.detached && child.pid != null) {
          try {
            process.kill(-child.pid, signal ?? 'SIGTERM');
          } catch {}
        } else {
          child.kill(signal);
        }
      }
    },
  };
}

import { randomUUID } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

/**
 * Provider-SESSION fork emulation for merge reviews (NOT Chat "Fork").
 *
 * For providers whose CLI has no native non-interactive `--fork` flag.
 * Technique: locate the source session file on disk, COPY it to a fresh
 * uuid, rewrite the internal session-id field so the copy is self-consistent,
 * and return the new id. The caller then spawns with `resume: true` on the copy.
 *
 * The source file is never touched — this is a true session fork, not a rename.
 *
 * Unleashd's Chat "Fork" button does not use this. That path is a soft handoff
 * (new conversation + draft/transcript text) via resumedFromConversationId.
 *
 * Synchronous on purpose: executeCommand is a synchronous factory
 * (returns a handle immediately, spawn happens eagerly). Session files
 * are small enough that sync fs I/O is acceptable here.
 *
 * Currently implemented:
 *   - codex   → ~/.codex/sessions/YYYY/MM/DD/rollout-<ts>-<uuid>.jsonl
 *                (rewrites payload.id on the first session_meta line)
 *   - gemini  → ~/.gemini/tmp/<projectHash>/chats/session-<ts>-<uuid>.json
 *                (rewrites top-level sessionId field)
 */

// Read $HOME fresh each call so tests can override via process.env.HOME
// without reaching into the module state. Production callers don't mutate
// HOME, so this costs nothing and keeps the module itself side-effect-free
// at import time.
const codexSessionsDir = () => path.join(os.homedir(), '.codex', 'sessions');
const geminiSessionsDir = () => path.join(os.homedir(), '.gemini', 'tmp');
const UUID_RE = /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i;

export type EmulatedForkResult = {
  newSessionId: string;
  newFilePath: string;
  sourceFilePath: string;
};

export type EmulatedHarness = 'codex' | 'gemini';

// Called by executeCommand when a fork is requested against a harness whose
// CLI has no native --fork flag. Returns the new session id to --resume.
// Harnesses with a native fork flag never reach this code path.
export function emulateFork(harness: EmulatedHarness, sourceSessionId: string): EmulatedForkResult {
  if (harness === 'codex') return emulateForkCodex(sourceSessionId);
  if (harness === 'gemini') return emulateForkGemini(sourceSessionId);
  throw new Error(`emulateFork: unsupported harness ${harness}`);
}

export function emulateForkCodex(sourceSessionId: string): EmulatedForkResult {
  const sourceFilePath = findCodexSessionFile(sourceSessionId);
  if (!sourceFilePath) {
    throw new Error(`Codex session file not found for id ${sourceSessionId}`);
  }

  const newSessionId = randomUUID();
  const now = new Date();
  const yyyy = String(now.getFullYear());
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const destDir = path.join(codexSessionsDir(), yyyy, mm, dd);
  fs.mkdirSync(destDir, { recursive: true });
  const tsStamp = now.toISOString().replace(/[:.]/g, '-');
  const newFilePath = path.join(destDir, `rollout-${tsStamp}-${newSessionId}.jsonl`);

  const raw = fs.readFileSync(sourceFilePath, 'utf-8');
  const lines = raw.split('\n');
  let metaRewritten = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line) continue;
    let entry: unknown;
    try {
      entry = JSON.parse(line);
    } catch {
      continue;
    }
    if (!metaRewritten && isCodexSessionMeta(entry)) {
      const payload = { ...(entry.payload as Record<string, unknown>), id: newSessionId };
      const rewritten = { ...entry, payload };
      lines[i] = JSON.stringify(rewritten);
      metaRewritten = true;
    }
  }
  if (!metaRewritten) {
    throw new Error(`Codex source file lacks session_meta: ${sourceFilePath}`);
  }
  fs.writeFileSync(newFilePath, lines.join('\n'));

  return { newSessionId, newFilePath, sourceFilePath };
}

export function emulateForkGemini(sourceSessionId: string): EmulatedForkResult {
  const sourceFilePath = findGeminiSessionFile(sourceSessionId);
  if (!sourceFilePath) {
    throw new Error(`Gemini session file not found for id ${sourceSessionId}`);
  }

  const newSessionId = randomUUID();
  const destDir = path.dirname(sourceFilePath);
  const tsStamp = new Date().toISOString().replace(/[:.]/g, '-');
  const newFilePath = path.join(destDir, `session-${tsStamp}-${newSessionId}.json`);

  const raw = fs.readFileSync(sourceFilePath, 'utf-8');
  const data = JSON.parse(raw) as Record<string, unknown>;
  data.sessionId = newSessionId;
  fs.writeFileSync(newFilePath, JSON.stringify(data, null, 2));

  return { newSessionId, newFilePath, sourceFilePath };
}

// --- internal: filesystem search --------------------------------------------

export function findCodexSessionFile(
  sessionId: string,
  sessionsRoot = codexSessionsDir()
): string | null {
  try {
    const years = listDirs(sessionsRoot);
    for (const y of years) {
      const months = listDirs(y);
      for (const m of months) {
        const days = listDirs(m);
        for (const d of days) {
          let files: string[];
          try {
            files = fs.readdirSync(d);
          } catch {
            continue;
          }
          for (const f of files) {
            if (!f.endsWith('.jsonl')) continue;
            const match = f.match(UUID_RE);
            if (match && match[1].toLowerCase() === sessionId.toLowerCase()) {
              return path.join(d, f);
            }
          }
        }
      }
    }
  } catch {
    return null;
  }
  return null;
}

function findGeminiSessionFile(sessionId: string): string | null {
  try {
    const projectDirs = listDirs(geminiSessionsDir());
    for (const proj of projectDirs) {
      const chats = path.join(proj, 'chats');
      let files: string[];
      try {
        files = fs.readdirSync(chats);
      } catch {
        continue;
      }
      for (const f of files) {
        if (!f.startsWith('session-') || !f.endsWith('.json')) continue;
        const match = f.match(UUID_RE);
        if (match && match[1].toLowerCase() === sessionId.toLowerCase()) {
          return path.join(chats, f);
        }
      }
    }
  } catch {
    return null;
  }
  return null;
}

function listDirs(parent: string): string[] {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(parent, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.filter((e) => e.isDirectory()).map((e) => path.join(parent, e.name));
}

function isCodexSessionMeta(
  entry: unknown
): entry is { type: string; payload: { id: string } & Record<string, unknown> } {
  if (!entry || typeof entry !== 'object') return false;
  const e = entry as { type?: unknown; payload?: unknown };
  if (e.type !== 'session_meta') return false;
  const p = e.payload;
  return !!p && typeof p === 'object' && typeof (p as { id?: unknown }).id === 'string';
}

import type { HarnessConfig, McpEncoding, McpServerSpec } from '../types.ts';

/**
 * Claude CLI harness config.
 *
 * Session management:
 *   Create: --session-id <uuid>
 *   Resume: --resume <uuid>
 *
 * IMPORTANT: --resume takes the session ID as its VALUE.
 * Combining --session-id <id> --resume is REJECTED by Claude CLI
 * (unless --fork-session is also passed). This was a real bug in
 * oompa_loompas that wasted half of all swarm iterations — and is
 * the reason this shared tool exists.
 */
/**
 * Claude takes MCP config as a single `--mcp-config` value that is either a
 * file path or an inline JSON document. Inline avoids a temp file we would
 * then have to reap.
 *
 * Buddy turns use `--strict-mcp-config` so the process has a deterministic MCP
 * surface. This intentionally does not merge the user's global MCP servers:
 * authority-bearing Buddy tools must not be shadowed by or mixed with an
 * unrelated workspace configuration. Ordinary Claude conversations do not
 * pass MCP config and keep the normal global configuration behavior.
 *
 * Claude has no per-server "required" knob. The harness-level `required`
 * capability therefore means that required servers are encoded in an explicit,
 * isolated process configuration; the caller still owns the Buddy tool contract.
 */
function claudeMcpEncoding(
  servers: Readonly<Record<string, McpServerSpec>>
): McpEncoding {
  const mcpServers: Record<string, unknown> = {};
  const env: Record<string, string> = {};
  for (const [name, spec] of Object.entries(servers)) {
    if (spec.env) {
      for (const [key, value] of Object.entries(spec.env)) {
        if (key in env && env[key] !== value) {
          throw new Error(`MCP servers require conflicting values for environment variable ${key}`);
        }
        env[key] = value;
      }
    }
    mcpServers[name] = {
      command: spec.command,
      args: [...spec.args],
      ...(spec.cwd ? { cwd: spec.cwd } : {}),
    };
  }
  return {
    args: ['--strict-mcp-config', '--mcp-config', JSON.stringify({ mcpServers })],
    ...(Object.keys(env).length > 0 ? { env } : {}),
  };
}

export const claudeConfig: HarnessConfig = {
  binary: 'claude',
  baseCmd: [],
  bypassFlags: ['--dangerously-skip-permissions'],
  modelFlag: '--model',
  promptVia: 'flag',
  promptFlag: '-p',
  stdin: 'prompt',
  stdout: 'jsonl',
  mcpCapability: 'required',
  sessionCreateFlags: (id) => ['--session-id', id],
  sessionResumeFlags: (id) => ['--resume', id],
  // Fork: --resume <id> --fork-session assigns a new session id while
  // inheriting the original transcript (tool_use + tool_result blocks intact).
  // The original session is left untouched.
  sessionForkFlags: (id) => ['--resume', id, '--fork-session'],

  // Claude CLI accepts --effort <level> with choices:
  //   low | medium | high | xhigh | max
  // See `claude --help`. Flag is session-wide and works with -p/--print.
  reasoningFlags: (level) => ['--effort', level],

  mcp: claudeMcpEncoding,
};

import { emulateForkCodex } from '../fork-emulation.ts';
import type { HarnessConfig, McpEncoding, McpServerSpec } from '../types.ts';

/**
 * Codex reads MCP config as TOML `-c key=value` fragments. TOML string values
 * are double-quoted with backslash escapes — exactly JSON string syntax — so
 * JSON.stringify is the correct quoter here, not a coincidence.
 */
function tomlString(value: string): string {
  return JSON.stringify(value);
}

function tomlStringArray(values: readonly string[]): string {
  return `[${values.map(tomlString).join(',')}]`;
}

function codexMcpEncoding(servers: Readonly<Record<string, McpServerSpec>>): McpEncoding {
  const args: string[] = [];
  const env: Record<string, string> = {};
  for (const [name, spec] of Object.entries(servers)) {
    args.push('-c', `mcp_servers.${name}.command=${tomlString(spec.command)}`);
    args.push('-c', `mcp_servers.${name}.args=${tomlStringArray(spec.args)}`);
    args.push('-c', `mcp_servers.${name}.enabled=true`);
    if (spec.required) args.push('-c', `mcp_servers.${name}.required=true`);
    if (spec.cwd) args.push('-c', `mcp_servers.${name}.cwd=${tomlString(spec.cwd)}`);
    if (spec.env && Object.keys(spec.env).length > 0) {
      args.push('-c', `mcp_servers.${name}.env_vars=${tomlStringArray(Object.keys(spec.env))}`);
      for (const [key, value] of Object.entries(spec.env)) {
        if (key in env && env[key] !== value) {
          throw new Error(`MCP servers require conflicting values for environment variable ${key}`);
        }
        env[key] = value;
      }
    }
  }
  return { args, ...(Object.keys(env).length > 0 ? { env } : {}) };
}

/**
 * Codex CLI harness config.
 *
 * Session management:
 *   Create: implicit (Codex assigns thread_id on first turn)
 *   Resume: `codex exec resume <thread_id>` (subcommand, not flag)
 *
 * Model and reasoning values are independent opaque inputs. The application
 * owns any legacy composite migration; this harness never guesses from suffixes.
 *
 * Working directory:
 *   -C <path> on first turn only. Omitted on resume (session has its own cwd).
 */

export const codexConfig: HarnessConfig = {
  binary: 'codex',
  baseCmd: ['exec'],
  // --skip-git-repo-check: skip git repo validation (needed for worktrees
  // where .git is a file, not a directory). Safe to include always.
  extraArgs: ['--skip-git-repo-check'],
  // --dangerously-bypass-approvals-and-sandbox: skip all confirmations.
  bypassFlags: ['--dangerously-bypass-approvals-and-sandbox'],
  modelFlag: '-m',
  promptVia: 'stdin',
  stdin: 'prompt',
  stdinPromptArg: '-',
  stdout: 'jsonl',
  mcpCapability: 'required',
  cwdFlag: '-C',

  // Resume changes the subcommand: 'exec resume <id>' instead of 'exec ...'
  // These args are inserted right after baseCmd in the build function.
  sessionResumeFlags: (id) => ['resume', id],

  // Codex has no native non-interactive fork flag (`codex fork` is
  // interactive, `codex exec resume` has no --fork). We fork by copying
  // the rollout file under ~/.codex/sessions/YYYY/MM/DD/ to a fresh uuid
  // (rewriting the first session_meta.payload.id), then --resume the copy.
  // Source file is untouched. See fork-emulation.ts.
  emulateFork: (sourceSessionId) => emulateForkCodex(sourceSessionId),

  // Standalone reasoning parameter. Passed through verbatim.
  reasoningFlags: (level) => ['-c', `model_reasoning_effort=${level}`],

  // MCP: one `-c` group per server. Additive — `-c` overlays the user's
  // ~/.codex/config.toml rather than replacing it, so globally-configured
  // servers stay available alongside the injected ones.
  // This is the only MCP path currently running in production (moved here
  // verbatim from unleashd's buddyCodexMcpArgs); byte-for-byte output shape
  // is pinned by test/mcp.test.ts.
  mcp: (servers) => codexMcpEncoding(servers),
};

import { emulateForkGemini } from '../fork-emulation.ts';
import type { HarnessConfig } from '../types.ts';

/**
 * Gemini CLI harness config.
 *
 * Session management:
 *   Gemini supports UUID-based resume: --resume <session-uuid>.
 *   Using the actual session ID avoids collisions when multiple
 *   conversations share the same working directory (--resume latest
 *   would always resume the most recent one, causing fights).
 *
 * Permissions:
 *   --yolo bypasses all confirmation prompts.
 *
 * No `mcp` encoder: Gemini CLI supports MCP through settings files, but its
 * current official command-line surface has no additive per-process inline
 * config argument or environment variable. `--allowed-mcp-server-names` only
 * filters already-configured servers. Re-verify the official configuration
 * reference before adding an encoder; do not guess `--mcp-config`.
 */
export const geminiConfig: HarnessConfig = {
  mcpCapability: 'none',
  binary: 'gemini',
  baseCmd: [],
  bypassFlags: ['--yolo'],
  modelFlag: '-m',
  promptVia: 'flag',
  promptFlag: '-p',
  stdin: 'close',
  stdout: 'jsonl',

  // Gemini accepts UUIDs for --resume (not just "latest").
  // Using the actual session ID prevents two conversations with the
  // same CWD from fighting over a single session.
  sessionResumeFlags: (id) => ['--resume', id],

  // Gemini has no --fork equivalent — `--resume` mutates the original
  // session. We fork by copying the session file under
  // ~/.gemini/tmp/<projectHash>/chats/ to a fresh uuid (rewriting the
  // top-level sessionId), then --resume the copy. See fork-emulation.ts.
  emulateFork: (sourceSessionId) => emulateForkGemini(sourceSessionId),
};

import type { Harness, HarnessConfig, HarnessName, McpCapability } from '../types.ts';
import { claudeConfig } from './claude.ts';
import { codexConfig } from './codex.ts';
import { cursorConfig } from './cursor.ts';
import { geminiConfig } from './gemini.ts';
import { museConfig } from './muse.ts';
import { opencodeConfig } from './opencode.ts';

const geminiAliasPattern = /^gemini\d+$/;

/** Registry of all known harness configs. One entry per CLI agent. */
export const registry: Record<Harness, HarnessConfig> = {
  claude: claudeConfig,
  codex: codexConfig,
  opencode: opencodeConfig,
  gemini: geminiConfig,
  cursor: cursorConfig,
  muse: museConfig,
};

export function isGeminiAlias(name: string): name is Extract<HarnessName, `gemini${number}`> {
  return geminiAliasPattern.test(name);
}

export function canonicalizeHarness(name: HarnessName | string): Harness {
  return isGeminiAlias(name) ? 'gemini' : (name as Harness);
}

/** Get a harness config by name. Throws on unknown harness. */
export function getHarness(name: HarnessName | string): HarnessConfig {
  const canonical = canonicalizeHarness(name);
  const config = registry[canonical as Harness];
  if (!config) {
    const known = Object.keys(registry).join(', ');
    throw new Error(`Unknown harness: "${name}". Known: ${known}`);
  }

  // Gemini aliases (gemini1/gemini2/gemini3) share CLI syntax but target
  // different binaries/wrappers so credentials stay isolated.
  if (name !== canonical) {
    return { ...config, binary: name };
  }

  return config;
}

/** List all known harness names. */
export function listHarnesses(): Harness[] {
  return Object.keys(registry) as Harness[];
}

/** Whether this harness can encode canonical per-process MCP server specs. */
export function harnessSupportsMcp(name: HarnessName | string): boolean {
  return getHarness(name).mcpCapability !== 'none';
}

/** Distinguishes best-effort injection from enforceable, fail-closed MCP. */
export function harnessMcpCapability(name: HarnessName | string): McpCapability {
  return getHarness(name).mcpCapability;
}

import type { HarnessConfig, McpEncoding, McpServerSpec } from '../types.ts';

/**
 * OpenCode CLI harness config.
 *
 * Session management:
 *   Create: implicit (session ID extracted from NDJSON output)
 *   Resume: --session <ses_xxx> --continue
 *   Guard: resume flags only emitted if session ID starts with 'ses_'
 *
 * Model normalization (κ — canonicalization):
 *   Legacy 'openai/...' → 'opencode/...' (backward compatibility)
 *   Bare 'muse-spark-*' → 'meta/muse-spark-*' (contributor preview via Meta API)
 *   Already-qualified 'meta/*' and 'opencode/*' pass through unchanged.
 */
/**
 * OpenCode has NO MCP command-line flag. Config arrives through the
 * OPENCODE_CONFIG_CONTENT env var as an inline JSON document — which is why
 * this encoder returns `env` and not `args`, and why the caller (unleashd)
 * could never implement this itself: only the spawn site can set env.
 *
 * Verified empirically on 2026-08-21 against the installed binary:
 *   - the server is loaded and dialed (`opencode mcp list` shows it, failing
 *     only because the probe command was not a real MCP server);
 *   - `cwd` IS honored — a probe server wrote its own pwd and it matched the
 *     configured cwd, not the process cwd;
 *   - the content MERGES with ~/.config/opencode/opencode.json rather than
 *     replacing it (the user's custom `meta` provider models survived), so
 *     this satisfies the additive-encoder rule.
 * OpenCode ignores unknown keys silently, so a schema typo will NOT error —
 * re-probe behaviourally rather than trusting acceptance.
 *
 * Shape differs from claude's: `command` is ONE array (binary followed by its
 * args), not split command/args. There is no per-server "required" knob, so
 * `spec.required` cannot be honored.
 *
 * Caveat: this OVERWRITES any OPENCODE_CONFIG_CONTENT already in the
 * environment. Nothing in this repo sets it; a caller that does would lose it.
 */
function opencodeMcpEncoding(servers: Readonly<Record<string, McpServerSpec>>): McpEncoding {
  const mcp: Record<string, unknown> = {};
  for (const [name, spec] of Object.entries(servers)) {
    mcp[name] = {
      type: 'local',
      command: [spec.command, ...spec.args],
      enabled: true,
      ...(spec.cwd ? { cwd: spec.cwd } : {}),
      ...(spec.env ? { environment: spec.env } : {}),
    };
  }
  return { env: { OPENCODE_CONFIG_CONTENT: JSON.stringify({ mcp }) } };
}

export const opencodeConfig: HarnessConfig = {
  binary: 'opencode',
  baseCmd: ['run'],
  // `opencode run --auto` = "auto-approve permissions that are not explicitly
  // denied". This was the only harness with an empty bypassFlags, so a caller
  // passing yolo/bypassPermissions got silent no-op and opencode still gated on
  // its interactive permission prompt — with no TTY to answer it.
  bypassFlags: ['--auto'],
  modelFlag: '-m',
  promptVia: 'cli-arg',
  stdin: 'close',
  stdout: 'jsonl',
  mcpCapability: 'inject',

  // Only resume if the session ID has the expected ses_ prefix
  sessionResumeFlags: (id) => (id.startsWith('ses_') ? ['--session', id, '--continue'] : []),

  // Fork: --session <id> --continue --fork inherits the transcript into a
  // new session id. Same ses_ prefix guard as resume.
  sessionForkFlags: (id) =>
    id.startsWith('ses_') ? ['--session', id, '--continue', '--fork'] : [],

  decomposeModel: (modelId) => {
    if (modelId.startsWith('openai/')) {
      return ['-m', `opencode/${modelId.slice('openai/'.length)}`];
    }
    if (modelId.startsWith('muse-spark')) {
      return ['-m', `meta/${modelId}`];
    }
    return ['-m', modelId];
  },

  mcp: (servers) => opencodeMcpEncoding(servers),
};

import {
  HEARTBEAT_CHECK_INTERVAL_MS,
  HEARTBEAT_SILENCE_THRESHOLD_MS,
} from './constants/timeouts.ts';
import type { NativeSessionProgress } from './native-progress.ts';
import type { StdoutStreamState, UnifiedAgentEvent } from './runtime-types.ts';

type TimerHandle = ReturnType<typeof setInterval>;

interface HeartbeatRuntime {
  now?: () => number;
  setIntervalFn?: (callback: () => void, intervalMs: number) => TimerHandle;
  clearIntervalFn?: (timer: TimerHandle) => void;
  checkIntervalMs?: number;
  silenceThresholdMs?: number;
  nativeProgress?: () => NativeSessionProgress | null;
  stdoutState?: () => StdoutStreamState | null;
}

export function createHeartbeat(
  enabled: boolean,
  emit: (event: UnifiedAgentEvent) => void,
  runtime: HeartbeatRuntime = {}
) {
  const now = runtime.now ?? Date.now;
  const setIntervalFn = runtime.setIntervalFn ?? setInterval;
  const clearIntervalFn = runtime.clearIntervalFn ?? clearInterval;
  const checkIntervalMs = runtime.checkIntervalMs ?? HEARTBEAT_CHECK_INTERVAL_MS;
  const silenceThresholdMs = runtime.silenceThresholdMs ?? HEARTBEAT_SILENCE_THRESHOLD_MS;
  let timer: ReturnType<typeof setInterval> | null = null;
  let lastUnifiedEventAt = now();
  let lastStdoutAt = now();
  let sawMeaningfulContent = false;

  return {
    start() {
      if (!enabled || timer) return;
      timer = setIntervalFn(() => {
        const timestamp = now();
        const unifiedEventSilenceMs = timestamp - lastUnifiedEventAt;
        if (unifiedEventSilenceMs < silenceThresholdMs) return;
        const nativeProgress = runtime.nativeProgress?.() ?? null;
        const stdoutState = runtime.stdoutState?.() ?? null;
        emit({
          type: 'progress',
          source: 'agent-cli.heartbeat',
          data: {
            unifiedEventSilentSeconds: Math.round(unifiedEventSilenceMs / 1000),
            rawStdoutSilentSeconds: Math.round((timestamp - lastStdoutAt) / 1000),
            phase: sawMeaningfulContent ? 'running' : 'startup',
            ...(stdoutState
              ? {
                  stdoutStreamEvent: stdoutState.event,
                  stdoutReadableFlowing: stdoutState.readableFlowing,
                  stdoutReadableLengthBytes: stdoutState.readableLength,
                }
              : {}),
            ...(nativeProgress
              ? {
                  nativeSessionAvailable: nativeProgress.available,
                  nativeSessionAdvanced: nativeProgress.advanced,
                  nativeSessionSilentSeconds: nativeProgress.silentSeconds,
                  ...(nativeProgress.sizeBytes !== undefined
                    ? { nativeSessionSizeBytes: nativeProgress.sizeBytes }
                    : {}),
                }
              : {}),
          },
        });
      }, checkIntervalMs);
    },
    stop() {
      if (!timer) return;
      clearIntervalFn(timer);
      timer = null;
    },
    markStdout() {
      lastStdoutAt = now();
    },
    markUnifiedEvent() {
      lastUnifiedEventAt = now();
    },
    markMeaningful() {
      sawMeaningfulContent = true;
    },
    sawMeaningfulContent() {
      return sawMeaningfulContent;
    },
  };
}

