/**
 * The opt-in `fullAuto` request option means "unattended but still sandboxed",
 * the softer sibling of bypassPermissions (which pushes
 * `--dangerously-bypass-approvals-and-sandbox` and removes the sandbox too).
 *
 * It used to emit `--full-auto`. That flag no longer exists on any `codex`
 * subcommand — verified against Codex CLI 2026-08: `codex --help` and
 * `codex exec --help` both report zero occurrences. `codex exec` is already
 * non-interactive, so there is no approval prompt to suppress; the sandbox
 * policy is the only remaining control, and `workspace-write` is the mode that
 * matches the old flag's behaviour.
 */
const CODEX_FULL_AUTO_ARGS = ['-s', 'workspace-write'] as const;

export function buildModeExtraArgs(
  harness: Harness,
  mode: TurnMode,
  yolo: boolean,
  cwd: string,
  codexFullAuto: boolean
): readonly string[] {
  if (mode === 'single-shot') {
    switch (harness) {
      case 'claude':
        return ['-p', '--output-format', 'text'];
      case 'gemini':
        return ['--output-format', 'text'];
      case 'codex':
        return codexFullAuto ? [...CODEX_FULL_AUTO_ARGS] : [];
      default:
        return [];
    }
  }

  switch (harness) {
    case 'claude': {
      const args = [
        '-p',
        '--verbose',
        '--output-format',
        'stream-json',
        '--include-partial-messages',
      ];
      if (yolo)
        args.push('--permission-mode', 'bypassPermissions', '--tools', 'default', '--add-dir', cwd);
      return args;
    }
    case 'codex':
      return codexFullAuto ? [...CODEX_FULL_AUTO_ARGS, '--json'] : ['--json'];
    case 'gemini':
      return ['--output-format', 'stream-json'];
    case 'opencode':
      return ['--format', 'json'];
    case 'cursor':
      return [];
    case 'muse':
      return ['--json'];
  }
}

import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  symlinkSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import { join } from 'node:path';
import type { McpServerSpec } from './types.ts';

/**
 * Muse MCP injection through a merged settings file.
 *
 * The muse CLI takes no MCP argv (unlike claude/codex) and no MCP env
 * (unlike opencode). Its only MCP surface is the `mcp_servers` block of the
 * user settings file (`$XDG_CONFIG_HOME/muse/settings.json`, else
 * `~/.config/muse/settings.json`). This module is the harness-owned HOW for
 * that surface: merge canonical server specs into a copy of the user's
 * settings and point the child at it via XDG_CONFIG_HOME.
 *
 * Fail-closed preserved: entries are written with explicit `mode`
 * (`required` when the spec demands it, `optional` otherwise) and the CLI
 * aborts the whole run when a required server fails startup. Verified
 * empirically against the installed binary: a nonexistent required command
 * ends the run with `run.terminal.failed` before any model step.
 *
 * Residue tradeoff: server args embed per-conversation ids, so the merged
 * dir is content-addressed (same content rewrites the same dir, concurrent
 * turns never share a path). Distinct server sets accumulate ~1KB dirs under
 * os.tmpdir(); they hold secrets (control tokens) with 0600/0700 modes.
 */

export interface MuseMcpConfigDir {
  /** Value to set XDG_CONFIG_HOME to for the child process. */
  readonly baseDir: string;
  /** Absolute path of the merged settings.json (for tests). */
  readonly settingsPath: string;
}

/** Where this process's muse CLI reads user configuration. */
export function museConfigRoot(): string {
  const base = process.env.XDG_CONFIG_HOME?.trim() || join(process.env.HOME ?? homedir(), '.config');
  return join(base, 'muse');
}

function stableStringify(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
  if (typeof value === 'object' && value !== null) {
    const entries = Object.entries(value as Record<string, unknown>)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([key, entry]) => `${JSON.stringify(key)}:${stableStringify(entry)}`);
    return `{${entries.join(',')}}`;
  }
  return JSON.stringify(value) ?? 'null';
}

function readUserSettings(root: string): Record<string, unknown> {
  const path = join(root, 'settings.json');
  if (!existsSync(path)) return {};
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(path, 'utf-8')) as unknown;
  } catch (error) {
    throw new Error(
      `Muse MCP encoding refuses to merge with unparseable settings at ${path}: ${error instanceof Error ? error.message : String(error)}`
    );
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error(`Muse settings at ${path} must be a JSON object`);
  }
  return parsed as Record<string, unknown>;
}

/**
 * Materialize a merged muse config dir for these servers and return the
 * XDG base to spawn with. Synchronous: called from buildCommand, which is
 * already a sync factory (same constraint as fork-emulation).
 */
export function buildMuseMcpConfigDir(
  servers: Readonly<Record<string, McpServerSpec>>
): MuseMcpConfigDir {
  const root = museConfigRoot();
  const userSettings = readUserSettings(root);
  const userServers =
    typeof userSettings['mcp_servers'] === 'object' && userSettings['mcp_servers'] !== null
      ? (userSettings['mcp_servers'] as Record<string, unknown>)
      : {};

  const mergedServers: Record<string, unknown> = { ...userServers };
  // The CLI gives MCP servers exactly the env declared here (no parent
  // inheritance observed), so parent-scoped store selection must be
  // forwarded explicitly or the child silently opens the default store.
  const forwardedEnv: Record<string, string> = {};
  const buddiesHome = process.env.BUDDIES_HOME?.trim();
  if (buddiesHome) forwardedEnv['BUDDIES_HOME'] = buddiesHome;
  for (const [name, spec] of Object.entries(servers)) {
    const encoded = {
      transport: 'stdio',
      command: spec.command,
      args: [...spec.args],
      ...(Object.keys(forwardedEnv).length > 0 || spec.env
        ? { env: { ...forwardedEnv, ...spec.env } }
        : {}),
      enabled: true,
      mode: spec.required ? 'required' : 'optional',
    };
    const existing = mergedServers[name];
    if (existing !== undefined && stableStringify(existing) !== stableStringify(encoded)) {
      throw new Error(
        `Muse MCP encoding refuses to shadow the user's own "${name}" server with a different spec`
      );
    }
    mergedServers[name] = encoded;
  }

  const mergedSettings: Record<string, unknown> = {
    ...userSettings,
    schema_version: 1,
    mcp_servers: mergedServers,
  };
  const digest = createHash('sha256').update(stableStringify(mergedSettings)).digest('hex').slice(0, 16);
  const baseDir = join(tmpdir(), 'unleashd-muse-mcp', digest);
  const generatedRoot = join(baseDir, 'muse');
  mkdirSync(generatedRoot, { recursive: true, mode: 0o700 });

  // Mirror the user's config entries (auth, trust, skills, hooks) so the
  // XDG redirect hides nothing. settings.json is the merged copy, not a link.
  if (existsSync(root)) {
    for (const entry of readdirSync(root)) {
      if (entry === 'settings.json') continue;
      const target = join(generatedRoot, entry);
      try {
        unlinkSync(target);
      } catch {
        // Absent (or dangling from a removed user file); relink below.
      }
      symlinkSync(join(root, entry), target);
    }
  }

  const settingsPath = join(generatedRoot, 'settings.json');
  writeFileSync(settingsPath, `${JSON.stringify(mergedSettings, null, 2)}\n`, { mode: 0o600 });
  return { baseDir, settingsPath };
}

import fs from 'node:fs';

import { findCodexSessionFile } from './fork-emulation.ts';

export interface NativeSessionProgress {
  available: boolean;
  advanced: boolean;
  silentSeconds: number;
  sizeBytes?: number;
}

interface NativeProgressRuntime {
  now?: () => number;
  sessionsRoot?: string;
}

/**
 * Observe Codex rollout progress using filesystem metadata only.
 *
 * This deliberately never opens or reads the rollout. Its only inputs are the
 * resolved session id, directory entry names, and stat metadata, so reasoning,
 * prompts, tool inputs, and model output cannot leak through diagnostics.
 */
export function createCodexNativeProgressProbe(
  sessionId: string,
  runtime: NativeProgressRuntime = {}
): { poll: () => NativeSessionProgress } {
  const now = runtime.now ?? Date.now;
  const file = findCodexSessionFile(sessionId, runtime.sessionsRoot);
  let initialStat: fs.Stats | undefined;
  if (file) {
    try {
      initialStat = fs.statSync(file);
    } catch {}
  }
  let lastSize = initialStat?.size;
  let lastMtimeMs = initialStat?.mtimeMs;
  let lastAdvanceAt = now();

  return {
    poll(): NativeSessionProgress {
      if (!file) {
        return {
          available: false,
          advanced: false,
          silentSeconds: Math.max(0, Math.round((now() - lastAdvanceAt) / 1000)),
        };
      }

      let stat: fs.Stats;
      try {
        stat = fs.statSync(file);
      } catch {
        return {
          available: false,
          advanced: false,
          silentSeconds: Math.max(0, Math.round((now() - lastAdvanceAt) / 1000)),
        };
      }

      const established = lastSize !== undefined && lastMtimeMs !== undefined;
      const advanced = established && (stat.size !== lastSize || stat.mtimeMs !== lastMtimeMs);
      if (advanced) lastAdvanceAt = now();
      lastSize = stat.size;
      lastMtimeMs = stat.mtimeMs;

      return {
        available: true,
        advanced,
        silentSeconds: Math.max(0, Math.round((now() - lastAdvanceAt) / 1000)),
        sizeBytes: stat.size,
      };
    },
  };
}

import { failureEvents } from '../diagnostics.ts';
import { asObject, asString } from '../json-utils.ts';
import type { UnifiedAgentEvent } from '../runtime-types.ts';

export function createClaudeParser(): (json: unknown) => UnifiedAgentEvent[] {
  let pendingTool: { name: string; inputJson: string } | null = null;

  return (json: unknown): UnifiedAgentEvent[] => {
    const obj = asObject(json);
    if (!obj) return [{ type: 'error', message: 'Claude emitted non-object JSON' }];

    if (obj.type === 'system' && asString(obj.subtype) === 'init') {
      return [{ type: 'turn.started' }];
    }

    if (obj.type === 'stream_event') {
      const event = asObject(obj.event);
      const eventType = asString(event?.type);
      if (eventType === 'content_block_delta') {
        const delta = asObject(event?.delta);
        const deltaType = asString(delta?.type);
        if (deltaType === 'text_delta' && asString(delta?.text)) {
          return [{ type: 'text.delta', text: asString(delta!.text)! }];
        }
        if (deltaType === 'input_json_delta' && pendingTool) {
          pendingTool.inputJson += asString(delta?.partial_json) ?? '';
        }
        return [];
      }

      if (eventType === 'content_block_start') {
        const block = asObject(event?.content_block);
        if (asString(block?.type) === 'tool_use') {
          pendingTool = { name: asString(block?.name) ?? 'tool', inputJson: '' };
        }
        return [];
      }

      if (eventType !== 'content_block_stop' || !pendingTool) return [];
      const { name, inputJson } = pendingTool;
      pendingTool = null;
      let input: Record<string, unknown> = {};
      if (inputJson) {
        try {
          input = JSON.parse(inputJson) as Record<string, unknown>;
        } catch {}
      }
      return [
        name === 'AskUserQuestion' || name === 'Task'
          ? { type: 'tool.use', name, input }
          : { type: 'tool.use', name, input, displayText: `${name}\n` },
      ];
    }

    if (obj.type === 'assistant') {
      const content = asObject(obj.message)?.content;
      if (!Array.isArray(content)) return [];
      for (const item of content) {
        const block = asObject(item);
        if (asString(block?.type) === 'tool_use' && asString(block?.name) === 'AskUserQuestion') {
          return [
            {
              type: 'text.delta',
              text: `\n<!--ask_user_question:${JSON.stringify(asObject(block?.input) ?? {})}-->\n`,
            },
          ];
        }
      }
      return [];
    }

    if (obj.type === 'user') {
      const content = asObject(obj.message)?.content;
      if (!Array.isArray(content)) return [];
      return content.flatMap((item): UnifiedAgentEvent[] => {
        const block = asObject(item);
        return block?.type === 'tool_result'
          ? [{ type: 'tool.result', output: block.content, isError: block.is_error === true }]
          : [];
      });
    }

    if (obj.type === 'result') {
      return asString(obj.subtype) === 'success'
        ? [{ type: 'turn.complete', reason: 'success' }]
        : failureEvents(asString(obj.result) ?? 'Claude returned an error');
    }

    return [];
  };
}

import { failureEvents } from '../diagnostics.ts';
import { asObject, asString } from '../json-utils.ts';
import type { UnifiedAgentEvent, UnifiedSubagentStatus } from '../runtime-types.ts';

const CODEX_COLLAB_TOOL_NAMES = new Set(['spawn_agent', 'wait', 'send_input']);

function collabToolInput(
  item: Record<string, unknown>,
  phase: 'started' | 'completed'
): Record<string, unknown> {
  const input: Record<string, unknown> = { _phase: phase };
  const prompt = asString(item.prompt);
  const senderThreadId = asString(item.sender_thread_id);
  const status = asString(item.status);
  if (prompt) input.prompt = prompt;
  if (senderThreadId) input.sender_thread_id = senderThreadId;
  if (status) input.status = status;
  if (Array.isArray(item.receiver_thread_ids)) input.receiver_thread_ids = item.receiver_thread_ids;
  const agentStates = asObject(item.agents_states);
  if (agentStates) input.agents_states = agentStates;
  return input;
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((entry): entry is string => typeof entry === 'string');
}

function normalizeCodexSubagentStatus(
  rawStatus: string | undefined,
  fallback: UnifiedSubagentStatus
): UnifiedSubagentStatus {
  if (!rawStatus) return fallback;
  switch (rawStatus) {
    case 'pending_init':
      return 'pending';
    case 'completed':
      return 'completed';
    case 'in_progress':
    case 'running':
      return 'running';
    default:
      break;
  }

  const lower = rawStatus.toLowerCase();
  if (lower.includes('error') || lower.includes('fail') || lower.includes('cancel')) {
    return 'error';
  }
  if (lower.includes('pending')) return 'pending';
  if (lower.includes('run') || lower.includes('progress')) return 'running';
  return fallback;
}

function formatCodexSubagentMessage(
  toolName: string,
  rawStatus: string | undefined,
  message: string | undefined
): string | undefined {
  if (message) return message;
  if (rawStatus === 'pending_init') return 'Pending initialization';

  const lower = rawStatus?.toLowerCase();
  if (lower) {
    if (lower.includes('error') || lower.includes('fail') || lower.includes('cancel')) {
      return 'Error';
    }
    if (lower.includes('pending')) return 'Pending';
  }

  if (rawStatus === 'in_progress' || rawStatus === 'running') {
    switch (toolName) {
      case 'spawn_agent':
        return 'Starting';
      case 'wait':
        return 'Waiting';
      case 'send_input':
        return 'Sending follow-up';
      default:
        return 'Running';
    }
  }

  return undefined;
}

function collabSubagentEvents(
  item: Record<string, unknown>,
  phase: 'started' | 'completed'
): UnifiedAgentEvent[] {
  const toolName = asString(item.tool);
  if (phase !== 'completed' || !toolName || !CODEX_COLLAB_TOOL_NAMES.has(toolName)) return [];

  const childIds = new Set(asStringArray(item.receiver_thread_ids));
  const agentStates = asObject(item.agents_states);
  if (agentStates) {
    for (const threadId of Object.keys(agentStates)) childIds.add(threadId);
  }
  if (childIds.size === 0) return [];

  const parentId = asString(item.sender_thread_id);
  const description = asString(item.prompt);
  const fallbackStatus: UnifiedSubagentStatus = toolName === 'spawn_agent' ? 'pending' : 'running';

  return [...childIds].map((id) => {
    const state = asObject(agentStates?.[id]);
    const rawStatus = asString(state?.status);
    const message = formatCodexSubagentMessage(toolName, rawStatus, asString(state?.message));
    return {
      type: 'subagent.state',
      id,
      status: normalizeCodexSubagentStatus(rawStatus, fallbackStatus),
      ...(parentId ? { parentId } : {}),
      ...(rawStatus ? { rawStatus } : {}),
      ...(description ? { description } : {}),
      ...(message ? { message } : {}),
    };
  });
}

export function parseCodex(json: unknown): UnifiedAgentEvent[] {
  const obj = asObject(json);
  if (!obj) return [{ type: 'error', message: 'Codex emitted non-object JSON' }];
  const type = asString(obj.type);
  if (!type) return [];

  switch (type) {
    case 'thread.started':
      return [{ type: 'progress', source: 'codex.thread_started' }];
    case 'turn.started':
      return [{ type: 'turn.started' }];
    case 'turn.completed':
      return [{ type: 'turn.complete', reason: 'success' }];
    case 'turn.failed': {
      const raw = obj.error;
      return failureEvents(
        asString(raw) ?? asString(asObject(raw)?.message) ?? JSON.stringify(raw ?? 'Unknown error')
      );
    }
    case 'error':
      return failureEvents(asString(obj.message) ?? JSON.stringify(obj), false);
    case 'item.started': {
      const item = asObject(obj.item);
      if (asString(item?.type) === 'command_execution' && asString(item?.command)) {
        const command = asString(item!.command)!;
        return [
          { type: 'tool.use', name: 'shell', input: { command }, displayText: `${command}\n` },
        ];
      }
      if (asString(item?.type) === 'collab_tool_call') {
        return [
          {
            type: 'tool.use',
            name: asString(item?.tool) ?? 'collab_tool',
            input: collabToolInput(item!, 'started'),
          },
          ...collabSubagentEvents(item!, 'started'),
        ];
      }
      return [
        {
          type: 'progress',
          source: 'codex.item_started',
          data: { itemType: asString(item?.type) ?? 'unknown' },
        },
      ];
    }
    case 'item.completed': {
      const item = asObject(obj.item);
      const itemType = asString(item?.type);
      if (!itemType)
        return [
          { type: 'progress', source: 'codex.item_completed', data: { itemType: 'unknown' } },
        ];
      if (itemType === 'agent_message' && asString(item?.text)) {
        return [{ type: 'text.delta', text: asString(item!.text)! }];
      }
      if (itemType === 'command_execution') {
        const input: Record<string, unknown> = { command: asString(item?.command) ?? '' };
        if (typeof item?.exit_code === 'number') input.exit_code = item.exit_code;
        return [{ type: 'tool.use', name: 'shell', input }];
      }
      if (itemType === 'file_change') {
        return [
          {
            type: 'tool.use',
            name: 'file_change',
            input: { changes: Array.isArray(item?.changes) ? item.changes : [] },
          },
        ];
      }
      if (itemType === 'mcp_tool_call') {
        return [
          { type: 'tool.use', name: asString(item?.name) ?? 'mcp_tool', input: {} },
          {
            type: 'tool.result',
            output: item?.result,
            isError: !!item?.error || item?.status === 'failed',
          },
        ];
      }
      if (itemType === 'web_search') {
        return [{ type: 'tool.use', name: 'web_search', input: {} }];
      }
      if (itemType === 'collab_tool_call') {
        return [
          {
            type: 'tool.use',
            name: asString(item?.tool) ?? 'collab_tool',
            input: collabToolInput(item!, 'completed'),
          },
          ...collabSubagentEvents(item!, 'completed'),
        ];
      }
      return [{ type: 'progress', source: 'codex.item_completed', data: { itemType } }];
    }
    default:
      return [{ type: 'progress', source: `codex.${type}` }];
  }
}

import { failureEvents } from '../diagnostics.ts';
import { asObject, asString, normalizeType } from '../json-utils.ts';
import type { UnifiedAgentEvent } from '../runtime-types.ts';

function extractMessageText(obj: Record<string, unknown>): string | undefined {
  const direct = asString(obj.content) ?? asString(obj.text);
  if (direct) return direct;
  const message = asObject(obj.message);
  const messageText = asString(message?.text) ?? asString(message?.content);
  if (messageText) return messageText;
  const content = message?.content;
  if (!Array.isArray(content)) return undefined;
  const chunks = content
    .map((entry) => {
      const item = asObject(entry);
      return asString(item?.type) === 'text' ? asString(item?.text) : undefined;
    })
    .filter(Boolean);
  return chunks.length > 0 ? chunks.join('') : undefined;
}

function resultEvents(obj: Record<string, unknown>): UnifiedAgentEvent[] {
  if (
    normalizeType(asString(obj.subtype)) === 'success' ||
    asString(obj.status) === 'success' ||
    asString(obj.reason) === 'success' ||
    obj.is_error === false
  ) {
    return [{ type: 'turn.complete', reason: 'success' }];
  }
  return failureEvents(
    asString(obj.error) ??
      asString(obj.message) ??
      `Cursor result failed: ${String(obj.subtype ?? obj.status ?? obj.reason ?? 'unknown')}`
  );
}

export function createCursorParser(): (json: unknown) => UnifiedAgentEvent[] {
  let lastAssistantText = '';

  return (json: unknown): UnifiedAgentEvent[] => {
    const obj = asObject(json);
    if (!obj) return [{ type: 'error', message: 'Cursor emitted non-object JSON' }];
    const type = asString(obj.type);
    if (!type) {
      return [
        { type: 'error', message: `Cursor JSON missing required "type": ${JSON.stringify(obj)}` },
      ];
    }

    if (type === 'system') {
      const subtype = normalizeType(asString(obj.subtype));
      if (subtype === 'init') {
        lastAssistantText = '';
        return [{ type: 'turn.started' }];
      }
      return [
        { type: 'progress', source: 'cursor.system', data: { subtype: subtype ?? 'unknown' } },
      ];
    }

    if (type === 'init' || type === 'turn.started') {
      lastAssistantText = '';
      return [{ type: 'turn.started' }];
    }

    if (type === 'assistant') {
      const content = extractMessageText(obj);
      if (!content) {
        return [
          {
            type: 'progress',
            source: 'cursor.message',
            data: { role: 'assistant', hasContent: false },
          },
        ];
      }
      if (content === lastAssistantText) return [];
      const delta =
        lastAssistantText && content.startsWith(lastAssistantText)
          ? content.slice(lastAssistantText.length)
          : content;
      lastAssistantText = content;
      return delta ? [{ type: 'text.delta', text: delta }] : [];
    }

    if (type === 'user') {
      return [
        {
          type: 'progress',
          source: 'cursor.message',
          data: { role: 'user', hasContent: !!extractMessageText(obj) },
        },
      ];
    }

    if (type === 'message' || type === 'text.delta') {
      const role = asString(obj.role);
      const content = extractMessageText(obj);
      if ((type === 'text.delta' || !role || role === 'assistant') && content) {
        return [{ type: 'text.delta', text: content }];
      }
      return [
        {
          type: 'progress',
          source: 'cursor.message',
          data: { role: role ?? 'unknown', hasContent: !!content },
        },
      ];
    }

    if (type === 'error') {
      const message = asString(obj.message) ?? asString(obj.error) ?? JSON.stringify(obj);
      return asString(obj.severity) === 'warning'
        ? [{ type: 'progress', source: 'cursor.warning', data: { message } }]
        : [{ type: 'error', message }];
    }

    if (type === 'tool_use' || type === 'tool') {
      return [
        {
          type: 'tool.use',
          name: asString(obj.tool_name) ?? asString(obj.name) ?? 'tool',
          input: asObject(obj.parameters) ?? asObject(obj.input) ?? {},
        },
      ];
    }

    if (type === 'tool_result') {
      const toolId = asString(obj.tool_id);
      return [
        {
          type: 'progress',
          source: 'cursor.tool_result',
          data: {
            status: asString(obj.status) ?? 'unknown',
            ...(toolId ? { tool_id: toolId } : {}),
          },
        },
      ];
    }

    if (type === 'result' || type === 'turn.complete') {
      lastAssistantText = '';
      return resultEvents(obj);
    }

    if (type === 'tool_call') return [];
    return [
      {
        type: 'error',
        message: `Cursor emitted unrecognized event type "${type}": ${JSON.stringify(obj)}`,
      },
    ];
  };
}

import { failureEvents } from '../diagnostics.ts';
import { asObject, asString } from '../json-utils.ts';
import type { UnifiedAgentEvent } from '../runtime-types.ts';

export function parseGemini(json: unknown): UnifiedAgentEvent[] {
  const obj = asObject(json);
  if (!obj) return [{ type: 'error', message: 'Gemini emitted non-object JSON' }];
  const type = asString(obj.type);
  if (!type) {
    return [
      { type: 'error', message: `Gemini JSON missing required "type": ${JSON.stringify(obj)}` },
    ];
  }

  if (type === 'init') return [{ type: 'turn.started' }];
  if (type === 'message') {
    const role = asString(obj.role);
    const content = asString(obj.content);
    return role === 'assistant' && content
      ? [{ type: 'text.delta', text: content }]
      : [
          {
            type: 'progress',
            source: 'gemini.message',
            data: { role: role ?? 'unknown', hasContent: !!content },
          },
        ];
  }
  if (type === 'error') {
    const message = asString(obj.message) ?? asString(obj.error) ?? JSON.stringify(obj);
    return asString(obj.severity) === 'warning'
      ? [{ type: 'progress', source: 'gemini.warning', data: { message } }]
      : [{ type: 'error', message }];
  }
  if (type === 'tool_use') {
    return [
      {
        type: 'tool.use',
        name: asString(obj.tool_name) ?? 'tool',
        input: asObject(obj.parameters) ?? {},
      },
    ];
  }
  if (type === 'tool_result') {
    const toolId = asString(obj.tool_id);
    return [
      {
        type: 'progress',
        source: 'gemini.tool_result',
        data: { status: asString(obj.status) ?? 'unknown', ...(toolId ? { tool_id: toolId } : {}) },
      },
    ];
  }
  if (type === 'result') {
    return asString(obj.status) === 'success'
      ? [{ type: 'turn.complete', reason: 'success' }]
      : failureEvents(
          asString(obj.error) ??
            asString(obj.message) ??
            `Gemini result failed: ${String(obj.status ?? 'unknown')}`
        );
  }

  return [
    {
      type: 'error',
      message: `Gemini emitted unrecognized event type "${type}": ${JSON.stringify(obj)}`,
    },
  ];
}

import type { UnifiedAgentEvent } from '../runtime-types.ts';
import type { Harness } from '../types.ts';
import { createClaudeParser } from './claude.ts';
import { parseCodex } from './codex.ts';
import { createCursorParser } from './cursor.ts';
import { parseGemini } from './gemini.ts';
import { parseMuse } from './muse.ts';
import { parseOpenCode } from './opencode.ts';

export type HarnessParser = (json: unknown) => UnifiedAgentEvent[];

export function createParser(harness: Harness): HarnessParser {
  switch (harness) {
    case 'claude':
      return createClaudeParser();
    case 'codex':
      return parseCodex;
    case 'opencode':
      return parseOpenCode;
    case 'gemini':
      return parseGemini;
    case 'cursor':
      return createCursorParser();
    case 'muse':
      return parseMuse;
  }
}

import { failureEvents } from '../diagnostics.ts';
import { asObject, asString } from '../json-utils.ts';
import type { UnifiedAgentEvent } from '../runtime-types.ts';

export function parseMuse(json: unknown): UnifiedAgentEvent[] {
  const obj = asObject(json);
  if (!obj) return [{ type: 'error', message: 'Muse emitted non-object JSON' }];
  const payloadType = asString(obj.payload_type);
  if (!payloadType) return [];
  const payload = asObject(obj.payload);

  switch (payloadType) {
    case 'run.lifecycle.started':
    case 'session.run.linked':
      return [{ type: 'turn.started' }];
    case 'run.output.delta': {
      const text = asString(payload?.text);
      return text ? [{ type: 'text.delta', text }] : [];
    }
    case 'run.terminal.completed': {
      const text = asString(payload?.text);
      if (text) {
        return [
          { type: 'text.delta', text },
          { type: 'turn.complete', reason: 'success' },
        ];
      }
      return [{ type: 'turn.complete', reason: 'success' }];
    }
    case 'task.lifecycle.failed':
    case 'run.terminal.failed': {
      const event = asObject(payload?.event);
      const reason =
        asString(event?.reason) ??
        asString(payload?.reason) ??
        asString(payload?.text) ??
        'Muse run failed';
      return failureEvents(reason);
    }
    case 'tool.result': {
      // The CLI executes MCP tools in-process; this is the observable
      // completion, with the namespaced tool name in correlation_facts.
      const facts = asObject(payload?.correlation_facts);
      const name = asString(facts?.tool_name) ?? 'mcp_tool';
      return [
        { type: 'tool.use', name, input: {} },
        ...(typeof payload?.text === 'string'
          ? [{
              type: 'tool.result' as const,
              output: payload.text,
              isError: facts?.outcome === 'error' || facts?.outcome === 'failed',
            }]
          : []),
      ];
    }
    case 'task.stream.linked':
    case 'task.lifecycle.proposed':
    case 'task.lifecycle.accepted':
    case 'task.lifecycle.started':
    case 'task.lifecycle.scheduled':
    case 'task.lifecycle.side_effect_intent':
    case 'task.lifecycle.completed': {
      const event = asObject(payload?.event);
      const operation = asString(event?.operation) ?? asString((payload as Record<string, unknown>)?.task_kind) ?? '';
      if (operation && !operation.includes('reminder') && !operation.includes('scope-reminder') && !operation.includes('goal-reminder')) {
        return [{ type: 'tool.use', name: operation, input: {} }];
      }
      return [];
    }
    default:
      return [];
  }
}

import { failureEvents } from '../diagnostics.ts';
import { asObject, asString, normalizeType } from '../json-utils.ts';
import type { UnifiedAgentEvent } from '../runtime-types.ts';

function extractAssistantText(obj: Record<string, unknown>): string | undefined {
  const direct = asString(obj.text);
  if (direct) return direct;
  const part = asObject(obj.part);
  const partText = asString(part?.text) ?? asString(asObject(part?.delta)?.text);
  if (partText) return partText;
  const message = asObject(obj.message);
  const messageText = asString(message?.text) ?? asString(message?.content);
  if (messageText) return messageText;
  const content = message?.content;
  if (!Array.isArray(content)) return undefined;
  const chunks = content.map((entry) => asString(asObject(entry)?.text)).filter(Boolean);
  return chunks.length > 0 ? chunks.join('') : undefined;
}

export function parseOpenCode(json: unknown): UnifiedAgentEvent[] {
  const obj = asObject(json);
  if (!obj) return [{ type: 'error', message: 'OpenCode emitted non-object JSON' }];
  const eventType =
    normalizeType(asString(obj.type)) ?? normalizeType(asString(asObject(obj.part)?.type));

  switch (eventType) {
    case 'step_start':
      return [{ type: 'turn.started' }];
    case 'text': {
      const text = extractAssistantText(obj);
      return text ? [{ type: 'text.delta', text }] : [];
    }
    case 'tool_use':
    case 'tool': {
      const part = asObject(obj.part) ?? {};
      const state = asObject(part.state);
      return [
        {
          type: 'tool.use',
          name: asString(part.tool) ?? asString(obj.tool) ?? 'tool',
          input: asObject(state?.input) ?? {},
        },
        ...(state?.status === 'completed' || state?.status === 'error'
          ? [{
              type: 'tool.result' as const,
              output: state.output,
              isError: state.status === 'error',
            }]
          : []),
      ];
    }
    case 'step_finish': {
      const part = asObject(obj.part);
      const reasonRaw = asString(part?.reason) ?? asString(obj.reason);
      const reason = normalizeType(reasonRaw);
      if (reason === 'tool_calls') return [];
      if (
        reason &&
        ['failed', 'error', 'abort', 'aborted', 'cancel', 'cancelled', 'canceled'].includes(reason)
      ) {
        return failureEvents(`OpenCode step failed (${reasonRaw ?? 'unknown'})`);
      }
      return [{ type: 'turn.complete', reason: 'success' }];
    }
    case 'done':
    case 'complete':
    case 'message_complete':
    case 'response_complete':
      return [{ type: 'turn.complete', reason: 'success' }];
    case 'error':
      return failureEvents(
        asString(obj.message) ?? asString(asObject(obj.error)?.message) ?? 'OpenCode error',
        false
      );
    default: {
      const text = extractAssistantText(obj);
      return text ? [{ type: 'text.delta', text }] : [];
    }
  }
}

import { type ChildProcess, spawn } from 'node:child_process';
import type { Readable } from 'node:stream';
import { buildCommand } from './build.ts';
import { resolveBinary } from './resolve.ts';
import type { RunOptions, RunResult } from './runtime-types.ts';
import type { CommandSpec } from './types.ts';

export function attachReadableStream(
  stream: Readable,
  onData: (data: Buffer) => void,
  onState?: RunOptions['onStdoutState']
): void {
  const report = (event: 'attached' | 'resume' | 'pause' | 'close') => {
    onState?.({
      event,
      readableFlowing: stream.readableFlowing,
      readableLength: stream.readableLength,
    });
  };
  stream.on('data', onData);
  stream.on('resume', () => report('resume'));
  stream.on('pause', () => report('pause'));
  stream.on('close', () => report('close'));
  report('attached');
  // A data listener normally enters flowing mode automatically. Make that
  // contract explicit: Node 24/macOS has been observed leaving a detached
  // Codex stdout socket paused with its first JSONL event unread.
  stream.resume();
}

export function runCommand(
  harness: string,
  options: RunOptions = {}
): { child: ChildProcess; spec: CommandSpec; done: Promise<RunResult> } {
  const spec = buildCommand(harness, options);
  const [bin, ...args] = spec.argv;
  // Cursor binary fallback: harness now builds `agent` but older installs
  // only have `cursor-agent`. Resolve through resolveBinary which probes
  // `agent` → `cursor-agent` fallback; on spawn we use the resolved path
  // so ENOENT never surfaces, but spec.argv stays canonical (`agent`).
  let effectiveBin = bin;
  try {
    effectiveBin = resolveBinary(bin);
  } catch {
    // let spawn handle ENOENT with its own error path
  }
  const useCallbacks = !!options.onStdout || !!options.onStderr;
  const child = spawn(effectiveBin, args, {
    cwd: options.cwd,
    detached: options.detached === true,
    // Harness-provided env is an overlay. Replacing process.env here would
    // drop PATH, credentials, and provider configuration from the child.
    ...(spec.env ? { env: { ...process.env, ...spec.env } } : {}),
    stdio: ['pipe', useCallbacks ? 'pipe' : 'inherit', useCallbacks ? 'pipe' : 'inherit'],
  });

  if (child.stdin) {
    if (spec.stdin === 'prompt' && spec.prompt) child.stdin.write(spec.prompt);
    if (spec.stdin !== 'pipe') child.stdin.end();
  }
  if (options.onStdout && child.stdout) {
    attachReadableStream(child.stdout, options.onStdout, options.onStdoutState);
  }
  if (options.onStderr && child.stderr) child.stderr.on('data', options.onStderr);

  const done = new Promise<RunResult>((resolve, reject) => {
    child.on('close', (code, signal) => resolve({ exitCode: code, signal, spec }));
    child.on('error', reject);
  });

  return { child, spec, done };
}

import { execSync } from 'node:child_process';

/**
 * Cache of resolved binary paths. Module-level for process lifetime caching.
 * Key: binary name, Value: absolute path.
 */
const cache = new Map<string, string>();

/**
 * Resolve a binary name to its absolute path via `which`.
 *
 * Caches results for the process lifetime. Throws if the binary
 * is not found on PATH.
 *
 * Why: babashka's ProcessBuilder with :dir can fail to find bare
 * command names on macOS. Resolving once via `which` and using
 * the absolute path avoids this issue.
 */
const CURSOR_FALLBACKS: Record<string, string[]> = {
  agent: ['cursor-agent'],
  'cursor-agent': ['agent'],
};

export function resolveBinary(name: string): string {
  const cached = cache.get(name);
  if (cached) return cached;

  const candidates = [name, ...(CURSOR_FALLBACKS[name] ?? [])];
  for (const candidate of candidates) {
    try {
      const p = execSync(`which ${candidate}`, { encoding: 'utf-8' }).trim();
      if (!p) continue;
      // Cache under requested name so future lookups don't re-probe fallback.
      cache.set(name, p);
      if (candidate !== name) cache.set(candidate, p);
      return p;
    } catch {
      // try fallback
    }
  }
  throw new Error(`Binary not found on PATH: ${name}`);
}

