  onStderr?: (data: Buffer) => void;
  onStdoutState?: (state: StdoutStreamState) => void;
  /** Start a separate process group for group-scoped termination. The owner keeps the child referenced. */
  detached?: boolean;
}

export interface StdoutStreamState {
  event: 'attached' | 'resume' | 'pause' | 'close';
  readableFlowing: boolean | null;
  readableLength: number;
}

export interface RunResult {
  exitCode: number | null;
  signal: NodeJS.Signals | null;
  spec: CommandSpec;
}

export type ClaudeReasoningLevel = 'low' | 'medium' | 'high' | 'xhigh' | 'max';
export const CODEX_REASONING_LEVELS = [
  'minimal',
  'low',
  'medium',
  'high',
  'xhigh',
  'max',
  'ultra',
] as const;
export type CodexReasoningLevel = (typeof CODEX_REASONING_LEVELS)[number];
export const MUSE_REASONING_LEVELS = ['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'ultra'] as const;
export type MuseReasoningLevel = (typeof MUSE_REASONING_LEVELS)[number];
export type TurnMode = 'conversation' | 'single-shot';
export type CompletionReason = 'success' | 'out_of_tokens' | 'error' | 'killed';
export type UnifiedSubagentStatus = 'pending' | 'running' | 'completed' | 'error';

export interface UnifiedSubagentStateEvent {
  type: 'subagent.state';
  id: string;
  status: UnifiedSubagentStatus;
  parentId?: string;
  rawStatus?: string;
  description?: string;
  message?: string;
}

type BaseExecuteCommandRequest<THarness extends HarnessName> = {
  harness: THarness;
  mode: TurnMode;
  prompt: string;
  cwd: string;
  model?: string;
  extraArgs?: readonly string[];
  /** Canonical stdio MCP servers; the selected harness owns provider-specific encoding. */
  mcpServers?: Readonly<Record<string, McpServerSpec>>;
  sessionId?: string;
  resumeSessionId?: string;
  forkSessionId?: string;
  yolo?: boolean;
  debugRawEvents?: boolean;
  /** Start a separate process group for group-scoped termination. The owner keeps the child referenced. */
  detached?: boolean;
};

type CodexExecuteCommandRequest = BaseExecuteCommandRequest<'codex'> & {
  reasoningEffort?: string;
  fullAuto?: boolean;
};

type ClaudeExecuteCommandRequest = BaseExecuteCommandRequest<'claude'> & {
  reasoningEffort?: string;
  fullAuto?: never;
};

type MuseExecuteCommandRequest = BaseExecuteCommandRequest<'muse'> & {
  reasoningEffort?: string;
  fullAuto?: never;
};

type NoExtraExecuteCommandRequest<THarness extends Exclude<HarnessName, 'codex' | 'claude' | 'muse'>> =
  BaseExecuteCommandRequest<THarness> & {
    reasoningEffort?: never;
    fullAuto?: never;
  };

export type ExecuteCommandRequest =
  | CodexExecuteCommandRequest
  | ClaudeExecuteCommandRequest
  | MuseExecuteCommandRequest
  | NoExtraExecuteCommandRequest<'opencode'>
  | NoExtraExecuteCommandRequest<'gemini'>
  | NoExtraExecuteCommandRequest<'cursor'>
  | NoExtraExecuteCommandRequest<GeminiAlias>;

export type UnifiedAgentEvent =
  | { type: 'session.started'; sessionId: string }
  | { type: 'turn.started' }
  | { type: 'text.delta'; text: string }
  | { type: 'tool.use'; name: string; input: Record<string, unknown>; displayText?: string }
  | { type: 'tool.result'; output: unknown; isError?: boolean }
  | UnifiedSubagentStateEvent
  | { type: 'progress'; source: string; data?: Record<string, unknown> }
  | { type: 'out_of_tokens'; message: string }
  | { type: 'error'; message: string }
  | { type: 'turn.complete'; reason: CompletionReason }
  | { type: 'stderr'; text: string };

export interface ExecuteCommandCompletion {
  reason: CompletionReason;
  exitCode: number | null;
  signal: NodeJS.Signals | null;
  sessionId: string;
  spec: CommandSpec;
}

export interface ExecuteCommandHandle {
  child: ChildProcess;
  spec: CommandSpec;
  events: AsyncIterable<UnifiedAgentEvent>;
  sessionId: Promise<string>;
  completed: Promise<ExecuteCommandCompletion>;
  stop: (signal?: NodeJS.Signals) => void;
}

export type ExecuteTurnRequest = ExecuteCommandRequest;
export type ExecuteTurnEvent = UnifiedAgentEvent;
export type ExecuteTurnCompletion = ExecuteCommandCompletion;
export type ExecuteTurnHandle = ExecuteCommandHandle;

export type RuntimeHarness = Harness;

import { canonicalizeHarness, getHarness } from './harnesses/index.ts';
import { asObject, asString } from './json-utils.ts';
import type { ExecuteCommandRequest } from './runtime-types.ts';
import type { Harness } from './types.ts';

export interface PreparedSession {
  buildSessionId?: string;
  resume: boolean;
  fork: boolean;
  resolvedSessionId: string;
}

export function prepareSession(request: ExecuteCommandRequest): PreparedSession {
  const canonicalHarness = canonicalizeHarness(request.harness);
  if (request.forkSessionId) {
    const harnessCfg = getHarness(canonicalHarness);
    if (harnessCfg.sessionForkFlags) {
      return {
        buildSessionId: request.forkSessionId,
        resume: false,
        fork: true,
        resolvedSessionId: '',
      };
    }
    if (harnessCfg.emulateFork) {
      const { newSessionId } = harnessCfg.emulateFork(request.forkSessionId);
      return {
        buildSessionId: newSessionId,
        resume: true,
        fork: false,
        resolvedSessionId: newSessionId,
      };
    }
    throw new Error(`Harness "${canonicalHarness}" does not support fork.`);
  }

  const buildSessionId = request.resumeSessionId ?? request.sessionId;
  return {
    buildSessionId,
    resume: !!request.resumeSessionId,
    fork: false,
    resolvedSessionId: buildSessionId ?? '',
  };
}

export function captureSessionIdFromJson(harness: Harness, json: unknown): string | undefined {
  const obj = asObject(json);
  if (!obj) return undefined;
  if (harness === 'codex' && obj.type === 'thread.started') {
    return asString(obj.thread_id);
  }
  if (harness === 'opencode') {
    const part = asObject(obj.part);
    return asString(
      obj.sessionID ??
        obj.sessionId ??
        obj.session_id ??
        part?.sessionID ??
        part?.sessionId ??
        part?.session_id
    );
  }
  if (harness === 'claude' || harness === 'gemini' || harness === 'cursor') {
    return asString(obj.session_id) ?? asString(obj.sessionId);
  }
  if (harness === 'muse') {
    const stream = asObject(obj.stream);
    if (asString(stream?.kind) === 'session' && asString(stream?.id)) {
      return asString(stream!.id);
    }
    return asString(obj.session_id) ?? asString(obj.sessionId);
  }
  return undefined;
}

/**
 * Canonical domain types for CLI agent invocation.
 *
 * These types encode the semantic space of "how to invoke a CLI agent."
 * All CLI syntax knowledge lives in HarnessConfig instances — one per agent.
 * The build function reads these configs to assemble argv deterministically.
 */

// =============================================================================
// Sum type: supported CLI agents
// =============================================================================

/** Adding a harness = adding one entry here + one config in harnesses/ */
export type Harness = 'claude' | 'codex' | 'opencode' | 'gemini' | 'cursor' | 'muse';
export type GeminiAlias = `gemini${number}`;
export type HarnessName = Harness | GeminiAlias;

// =============================================================================
// Prompt & stdin behavior
// =============================================================================

/**
 * How the prompt text is delivered to the CLI process.
 *
 * flag:     Value of a named flag (e.g. `-p "prompt"`)
 * cli-arg:  Last positional argument (e.g. `opencode run "prompt"`)
 * cli-sep:  After a separator (e.g. `codex exec -- "prompt"`)
 * stdin:    Written to the child process stdin, optionally with stdinPromptArg
 */
export type PromptDelivery = 'flag' | 'cli-arg' | 'cli-sep' | 'stdin';

/**
 * What the caller should do with process stdin after spawning.
 *
 * close:    Write "" and close immediately (prevent hang)
 * prompt:   Write the prompt text then close
 * pipe:     Leave open for caller to manage (interactive mode)
 */
export type StdinBehavior = 'close' | 'prompt' | 'pipe';

/**
 * What the caller should expect from process stdout.
 *
 * NOTE ON MOTIVATION: Even when CLI agents self-persist to disk (like Gemini or Codex),
 * they typically only write the session file at the very end of a turn.
 * Progressive stdout streaming (jsonl) is mandatory for real-time UI interactivity
 * (the "typewriter" effect) to prevent the UI from appearing frozen during long
 * generation tasks. Disk should be treated as a persistence/rehydration layer,
 * while stdout is the live interaction layer.
 *
 * jsonl:    Stream of JSON lines (claude, codex, opencode, gemini)
 * text:     Plain text output (single-shot mode)
 * ignore:   Output is irrelevant or handled out-of-band
 */
export type StdoutBehavior = 'jsonl' | 'text' | 'ignore';

// =============================================================================
// MCP (Model Context Protocol) servers
// =============================================================================

/**
 * Canonical, provider-agnostic description of one stdio MCP server.
 *
 * Callers describe WHAT to launch; each HarnessConfig.mcp encoder owns HOW that
 * gets expressed on its CLI (TOML `-c` fragments, a JSON flag, an env var, ...).
 * No caller should ever encode per-CLI MCP syntax itself.
 */
export interface McpServerSpec {
  readonly command: string;
  readonly args: readonly string[];
  readonly cwd?: string;
  /**
   * Environment requested for the MCP subprocess. Some CLIs can only forward
   * these through their own process environment, so values are kept out of
   * argv/config text but are not isolated from the harness process itself.
   */
  readonly env?: Readonly<Record<string, string>>;
  /** Fail the turn if the server cannot start, rather than running without it. */
  readonly required?: boolean;
}

/**
 * Strength of a harness's MCP contract.
 *
 * `inject` means the CLI accepts configuration but may continue when that
 * server fails. It is not sufficient for authority-bearing tools. `required`
 * means the harness can make MCP startup a turn-admission requirement.
 * Product policy belongs to the caller; this type only reports harness truth.
 */
export type McpCapability = 'none' | 'inject' | 'required';

/**
 * The result of encoding MCP servers for one harness: extra argv entries,
 * extra process env, or both. A harness may need only one of the two
 * (opencode is env-only; claude and codex are args-only).
 */
export interface McpEncoding {
  readonly args?: readonly string[];
  readonly env?: Readonly<Record<string, string>>;
}

// =============================================================================
// Harness config — pure data describing CLI syntax
// =============================================================================

/**
 * Pure data structure describing how to invoke a CLI agent.
 *
 * One instance per harness. No imperative code — only small pure functions
 * for model decomposition and session flag construction.
 *
 * This is the ONLY place that encodes CLI flag syntax.
 */
export interface HarnessConfig {
  /** CLI binary name (e.g. 'claude', 'codex') */
  readonly binary: string;

  /** Subcommand(s) after binary (e.g. ['exec'] for codex, [] for claude) */
  readonly baseCmd: readonly string[];

  /** Flags to bypass all confirmation prompts */
  readonly bypassFlags: readonly string[];

  /**
   * Encode MCP servers for this CLI.
   *
   * ABSENT means this harness has NO MCP support at all — not "not wired up
   * yet". buildCommand rejects required servers and ignores optional servers
   * for such harnesses. `harnessSupportsMcp(name)` lets callers reject an
   * incompatible job before building it. Every harness that leaves this field
   * out carries a comment saying why.
   *
   * Encoders are additive: they must never disable the user's own
   * globally-configured MCP servers.
   */
  readonly mcpCapability: McpCapability;
  readonly mcp?: (servers: Readonly<Record<string, McpServerSpec>>) => McpEncoding;

  /** Flag name for model selection (e.g. '--model' or '-m') */
  readonly modelFlag: string;

  /** How the prompt is delivered to the CLI */
  readonly promptVia: PromptDelivery;

  /** Flag name when promptVia is 'flag' (e.g. '-p') */
  readonly promptFlag?: string;

  /** Separator when promptVia is 'cli-sep' (e.g. '--') */
  readonly promptSep?: string;

  /** What the caller should do with process stdin */
  readonly stdin: StdinBehavior;

  /** Positional marker telling the CLI to read the prompt from stdin (for example Codex `-`). */
  readonly stdinPromptArg?: string;

  /** What the caller should expect from process stdout */
  readonly stdout: StdoutBehavior;

  /** Extra args appended to all commands (e.g. ['--output-format', 'stream-json']) */
  readonly extraArgs?: readonly string[];

  /** CLI flag for working directory (undefined = use process cwd option) */
  readonly cwdFlag?: string;

  /** Flags for creating a new session with this ID */
  readonly sessionCreateFlags?: (sessionId: string) => readonly string[];

  /**
   * Flags for resuming an existing session.
   * For codex, this returns subcommand args ('resume', id) that go after baseCmd.
   * For claude, this returns flag args ('--resume', id).
   */
  readonly sessionResumeFlags?: (sessionId: string) => readonly string[];

  /**
   * Provider-SESSION fork strategy for merge reviews — NOT Unleashd's Chat
   * "Fork" button. Chat Fork is a soft handoff (new conversation + draft /
   * pasted transcript) and never sets these fields.
   *
   * Two mutually-exclusive shapes, one per harness:
   *
   *   NATIVE:   sessionForkFlags is set → CLI has a real fork flag
   *             (claude `--resume <id> --fork-session`, opencode
   *             `--session <id> --continue --fork`). executeCommand
   *             passes fork=true to buildCommand and the CLI mints a new id.
   *
   *   EMULATED: emulateFork is set → no CLI flag exists, so we copy the
   *             source session file to a new uuid on disk and then --resume
   *             the copy. Source stays byte-identical. See fork-emulation.ts.
   *
   *   NEITHER:  harness does not support merge session-fork — executeCommand
   *             throws if a caller passes forkSessionId. Chat soft Fork is
   *             still fine without these.
   *
   * The two are mutually exclusive by construction: a harness either has
   * a native fork flag OR needs emulation, never both.
   */
  readonly sessionForkFlags?: (sessionId: string) => readonly string[];

  /**
   * Emulated-fork implementation for harnesses without a native fork flag.
   * Called with the SOURCE session id; returns the new session id to --resume.
   * Must be synchronous (executeCommand is a sync factory).
   */
  readonly emulateFork?: (sourceSessionId: string) => { readonly newSessionId: string };

  /**
   * Model ID decomposition. Returns the full set of flags for model selection.
   * When provided, replaces the default `[modelFlag, modelId]` behavior.
   *
   * Used for:
   * - Codex composite IDs: 'gpt-5.3-codex-high' → ['-m', 'gpt-5.3-codex', '-c', 'model_reasoning_effort=high']
   * - OpenCode legacy format: 'openai/foo' → ['-m', 'opencode/foo']
   */
  readonly decomposeModel?: (modelId: string) => readonly string[];

  /**
   * Reasoning/effort flags. Called when BuildOptions.reasoning is set.
   * Currently used by codex (`-c model_reasoning_effort=X`) and claude
   * (`--effort X`). Returns flags to append, or empty array if not supported.
   *
   * This is separate from decomposeModel because oompa passes reasoning
   * as a standalone parameter (codex:model:reasoning), while claude-web-view
   * encodes it in the composite model ID (gpt-5.3-codex-high).
   * Both paths produce the same CLI flags.
   */
  readonly reasoningFlags?: (level: string) => readonly string[];
}

// =============================================================================
// Build options — what the caller provides
// =============================================================================

/** Options for building a CLI command. Caller provides these. */
export interface BuildOptions {
  /** Model identifier (harness-specific, passed through or decomposed) */
  model?: string;

  /** Prompt text */
  prompt?: string;

  /** Session ID (for create or resume) */
  sessionId?: string;

  /** Whether to resume an existing session (vs create new) */
  resume?: boolean;

  /**
   * Whether to FORK an existing session — inherit its full transcript into a
   * new session id, leaving the original untouched. Use with sessionId set to
   * the SOURCE session (the one being forked from).
   *
   * Only valid for harnesses that set sessionForkFlags. For harnesses without
   * native support (codex, gemini), caller must emulate via cp+resume before
   * calling buildCommand — see sessionForkFlags docs on HarnessConfig.
   *
   * Mutually exclusive with `resume` — fork takes precedence.
   */
  fork?: boolean;

  /** Working directory (used with cwdFlag or passed to process options) */
  cwd?: string;

  /** Whether to include permissions bypass flags */
  bypassPermissions?: boolean;

  /**
   * Reasoning/effort level.
   *   codex  → `-c model_reasoning_effort=X`
   *   claude → `--effort X`  (low | medium | high | xhigh | max)
   *
   * Two ways to specify effort for codex:
   * 1. Composite model ID: model='gpt-5.3-codex-high' (decomposeModel handles it)
   * 2. Separate reasoning: model='gpt-5.3-codex', reasoning='high' (this field)
   *
   * If the model ID already encodes effort, this field is ignored.
   * Ignored for harnesses without reasoningFlags (opencode, gemini, cursor).
   */
  reasoning?: string;

  /** Extra args appended after all generated args (project-specific flags) */
  extraArgs?: readonly string[];

  /**
   * MCP servers to expose to the agent, keyed by server name.
   *
   * Encoded by the harness config's `mcp` encoder. Harnesses with no `mcp`
   * encoder ignore this field entirely (see HarnessConfig.mcp).
   */
  mcpServers?: Readonly<Record<string, McpServerSpec>>;
}

// =============================================================================
// Command spec — what the tool outputs
// =============================================================================

/**
 * Everything a caller needs to spawn the CLI process.
 * The build function produces this; callers exec it.
 */
export interface CommandSpec {
  /** Full argv: [binary, ...args] */
  argv: string[];

  /** What the caller should do with process stdin */
  stdin: StdinBehavior;

  /** What the caller should expect from process stdout */
  stdout: StdoutBehavior;

  /** The prompt text (for stdin delivery or caller reference) */
  prompt?: string;

  /**
   * Extra environment variables the process must be spawned with (e.g.
   * opencode's OPENCODE_CONFIG_CONTENT). MERGE these over the inherited
   * environment — never use them as a replacement env.
   */
  env?: Readonly<Record<string, string>>;
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { buildCommand } from '../src/build.ts';
import { listHarnesses } from '../src/harnesses/index.ts';
import { resolveBinary } from '../src/resolve.ts';

// =============================================================================
// Claude
// =============================================================================

describe('claude', () => {
  it('creates session with --session-id on first turn', () => {
    const spec = buildCommand('claude', {
      model: 'opus',
      prompt: 'hello',
      sessionId: 'abc-123',
    });
    // Prompt NOT in argv because stdin is 'prompt'
    assert.deepStrictEqual(spec.argv, ['claude', '--model', 'opus', '--session-id', 'abc-123']);
    assert.strictEqual(spec.prompt, 'hello');
    assert.strictEqual(spec.stdin, 'prompt');
  });

  it('resumes with --resume <id>, NOT --session-id + --resume', () => {
    const spec = buildCommand('claude', {
      model: 'opus',
      prompt: 'continue',
      sessionId: 'abc-123',
      resume: true,
    });

    // The resume bug: --session-id must NOT appear when resuming.
    // Claude CLI rejects --session-id X --resume (without --fork-session).
    assert.ok(
      !spec.argv.includes('--session-id'),
      `--session-id must NOT appear in resume command. Got: ${JSON.stringify(spec.argv)}`
    );
    // Prompt NOT in argv because stdin is 'prompt'
    assert.deepStrictEqual(spec.argv, ['claude', '--resume', 'abc-123', '--model', 'opus']);
    assert.strictEqual(spec.prompt, 'continue');
  });

  it('forks with --resume <id> --fork-session', () => {
    const spec = buildCommand('claude', {
      model: 'opus',
      prompt: 'branch off',
      sessionId: 'abc-123',
      fork: true,
    });
    assert.ok(spec.argv.includes('--resume'));
    assert.ok(spec.argv.includes('abc-123'));
    assert.ok(spec.argv.includes('--fork-session'));
    assert.ok(
      !spec.argv.includes('--session-id'),
      `--session-id must NOT appear in fork command. Got: ${JSON.stringify(spec.argv)}`
    );
  });

  it('includes bypass flags when requested', () => {
    const spec = buildCommand('claude', {
      prompt: 'test',
      bypassPermissions: true,
    });
    assert.ok(spec.argv.includes('--dangerously-skip-permissions'));
  });

  it('omits bypass flags when not requested', () => {
    const spec = buildCommand('claude', { prompt: 'test' });
    assert.ok(!spec.argv.includes('--dangerously-skip-permissions'));
  });

  it('stdin is prompt (Claude reads prompt from stdin)', () => {
    const spec = buildCommand('claude', { prompt: 'test' });
    assert.strictEqual(spec.stdin, 'prompt');
  });
});

// =============================================================================
// Codex
// =============================================================================

describe('codex', () => {
  it('builds first turn with exec, -C, and stdin prompt delivery', () => {
    const spec = buildCommand('codex', {
      model: 'gpt-5.3-codex-high',
      prompt: 'hello',
      cwd: '/tmp/work',
    });
    assert.deepStrictEqual(spec.argv, [
      'codex',
      'exec',
      '-C',
      '/tmp/work',
      '-m',
      'gpt-5.3-codex-high',
      '--skip-git-repo-check',
      '-',
    ]);
    assert.strictEqual(spec.prompt, 'hello');
    assert.strictEqual(spec.stdin, 'prompt');
  });

  it('fork throws — codex has no native non-interactive fork (TBD cp+resume)', () => {
    assert.throws(
      () =>
        buildCommand('codex', {
          prompt: 'branch off',
          sessionId: 'thread-abc',
          fork: true,
        }),
      /does not natively support fork/
    );
  });

  it('resume restructures command: exec resume <id>', () => {
    const spec = buildCommand('codex', {
      model: 'gpt-5.3-codex-high',
      prompt: 'continue',
      sessionId: 'thread-abc',
      resume: true,
    });
    // 'resume' and thread ID go right after 'exec'
    assert.strictEqual(spec.argv[0], 'codex');
    assert.strictEqual(spec.argv[1], 'exec');
    assert.strictEqual(spec.argv[2], 'resume');
    assert.strictEqual(spec.argv[3], 'thread-abc');
    assert.strictEqual(spec.argv.at(-1), '-');
    assert.ok(!spec.argv.includes('continue'));
    assert.strictEqual(spec.stdin, 'prompt');
  });

  it('suppresses -C on resume', () => {
    const spec = buildCommand('codex', {
      model: 'gpt-5.3-codex',
      prompt: 'continue',
      sessionId: 'thread-abc',
      resume: true,
      cwd: '/tmp/work',
    });
    assert.ok(
      !spec.argv.includes('-C'),
      `-C must NOT appear in resume command. Got: ${JSON.stringify(spec.argv)}`
    );
  });

  it('passes suffix-looking model IDs through without guessing reasoning', () => {
    const spec = buildCommand('codex', { model: 'gpt-example-ultra', prompt: 'test' });
    const mIdx = spec.argv.indexOf('-m');
    assert.notStrictEqual(mIdx, -1);
    assert.strictEqual(spec.argv[mIdx + 1], 'gpt-example-ultra');
    assert.ok(!spec.argv.includes('-c'));
  });

  it('passes standalone models directly (no decomposition)', () => {
    const spec = buildCommand('codex', { model: 'gpt-5.3-codex-spark', prompt: 'test' });
    const mIdx = spec.argv.indexOf('-m');
    assert.strictEqual(spec.argv[mIdx + 1], 'gpt-5.3-codex-spark');
    assert.ok(!spec.argv.includes('-c'), 'standalone model should not have -c flag');
  });

  it('passes reasoning independently for medium and xhigh', () => {
    for (const effort of ['medium', 'xhigh']) {
      const spec = buildCommand('codex', {
        model: 'gpt-example-ultra',
        prompt: 'test',
        reasoning: effort,
      });
      assert.ok(spec.argv.includes('gpt-example-ultra'));
      assert.ok(
        spec.argv.includes(`model_reasoning_effort=${effort}`),
        `missing effort for ${effort}`
      );
    }
  });

  it('includes bypass flags when requested', () => {
    const spec = buildCommand('codex', {
      prompt: 'test',
      bypassPermissions: true,
    });
    assert.ok(spec.argv.includes('--dangerously-bypass-approvals-and-sandbox'));
  });
});

