describe('reasoning', () => {
  it('standalone reasoning adds -c flag for codex', () => {
    const spec = buildCommand('codex', {
      model: 'gpt-5.3-codex',
      prompt: 'test',
      reasoning: 'high',
    });
    assert.ok(spec.argv.includes('-c'));
    assert.ok(spec.argv.includes('model_reasoning_effort=high'));
  });

  it('adds reasoning once even when a model ID has an effort-like suffix', () => {
    const spec = buildCommand('codex', {
      model: 'gpt-5.3-codex-high',
      prompt: 'test',
      reasoning: 'high',
    });
    const cFlags = spec.argv.filter((f) => f.startsWith('model_reasoning_effort='));
    assert.strictEqual(
      cFlags.length,
      1,
      `expected 1 reasoning flag, got ${cFlags.length}: ${JSON.stringify(spec.argv)}`
    );
  });

  it('standalone reasoning works for all effort levels', () => {
    for (const level of ['minimal', 'low', 'medium', 'high', 'max', 'xhigh']) {
      const spec = buildCommand('codex', {
        model: 'gpt-5.3-codex',
        prompt: 'test',
        reasoning: level,
      });
      assert.ok(
        spec.argv.includes(`model_reasoning_effort=${level}`),
        `missing effort for ${level}`
      );
    }
  });

  it('claude reasoning adds --effort flag', () => {
    const spec = buildCommand('claude', {
      model: 'opus',
      prompt: 'test',
      reasoning: 'high',
    });
    const effortIdx = spec.argv.indexOf('--effort');
    assert.ok(effortIdx >= 0, `missing --effort flag: ${JSON.stringify(spec.argv)}`);
    assert.strictEqual(spec.argv[effortIdx + 1], 'high');
  });

  it('claude reasoning works for all effort levels', () => {
    for (const level of ['low', 'medium', 'high', 'xhigh', 'max']) {
      const spec = buildCommand('claude', {
        model: 'opus',
        prompt: 'test',
        reasoning: level,
      });
      const effortIdx = spec.argv.indexOf('--effort');
      assert.ok(effortIdx >= 0, `missing --effort for ${level}`);
      assert.strictEqual(spec.argv[effortIdx + 1], level, `wrong effort value for ${level}`);
    }
  });

  it('reasoning is ignored for harnesses without reasoningFlags', () => {
    for (const harness of ['opencode', 'gemini', 'cursor']) {
      const spec = buildCommand(harness, {
        prompt: 'test',
        reasoning: 'high',
      });
      assert.ok(!spec.argv.includes('--effort'), `${harness} leaked --effort`);
      assert.ok(!spec.argv.some((f) => f.includes('reasoning')), `${harness} leaked reasoning`);
    }
  });
});

