describe('model loop', () => {
  // All known model IDs from both codebases
  const ALL_MODELS: Record<string, string[]> = {
    claude: ['fable', 'opus', 'sonnet', 'haiku'],
    codex: [
      'gpt-5.6-sol',
      'gpt-5.6-terra',
      'gpt-5.6-luna',
      'gpt-5.5',
      'gpt-6-astra',
      'gpt-5.3-codex-high',
      'gpt-5.3-codex-medium',
      'gpt-5.3-codex-xhigh',
      'gpt-5.3-codex-spark',
      'gpt-5.3-codex-spark-high',
      'gpt-5.3-codex-spark-medium',
      'gpt-5.3-codex-spark-xhigh',
    ],
    opencode: [
      'opencode/big-pickle',
      'opencode/gpt-5-nano',
      'opencode/kimi-k2.5-free',
      'opencode/minimax-m2.5-free',
      'openai/gpt-5', // legacy format
      'meta/muse-spark-1.1',
      'meta/muse-spark-1.2-contributor',
      'muse-spark-1.2-contributor', // bare form → meta/ qualified
    ],
    gemini: ['gemini-2.5-pro', 'gemini-2.5-flash'],
    cursor: [
      'composer-2.5',
      'cursor-grok-4.5-high',
      'cursor-grok-4.5-medium',
      'cursor-grok-4.5-low',
    ],
    muse: ['muse-spark-1.1', 'muse-spark-1.2-contributor'],
  };

  function expectedBinary(harness: string): string {
    if (harness === 'cursor') return 'agent';
    return harness;
  }

  for (const [harness, models] of Object.entries(ALL_MODELS)) {
    for (const model of models) {
      it(`${harness}/${model}: builds valid create command`, () => {
        const spec = buildCommand(harness, {
          model,
          prompt: 'test prompt',
          sessionId: 'test-session',
          bypassPermissions: true,
        });
        // Basic sanity: argv starts with the binary
        assert.strictEqual(spec.argv[0], expectedBinary(harness));
        // Model appears in argv (either directly, decomposed, or normalized).
        // OpenCode normalizes openai/X → opencode/X, so check both forms.
        const normalized = model.replace(/^openai\//, 'opencode/');
        const hasModel = spec.argv.some(
          (a) =>
            a.includes(model) ||
            a.includes(normalized) ||
            a.includes(model.split('-').slice(0, -1).join('-'))
        );
        assert.ok(
          hasModel,
          `model "${model}" (or normalized "${normalized}") not found in argv: ${JSON.stringify(spec.argv)}`
        );
      });

      it(`${harness}/${model}: builds valid resume command`, () => {
        const spec = buildCommand(harness, {
          model,
          prompt: 'continue',
          sessionId: 'test-session',
          resume: true,
        });
        assert.strictEqual(spec.argv[0], expectedBinary(harness));
        // Muse uses --session-id for both create and resume (unlike Claude's --resume)
        if (harness === 'muse') {
          assert.ok(
            spec.argv.includes('--session-id'),
            `muse should have --session-id on resume for ${model}`
          );
        } else {
          // No session-create flags in resume (Claude's --session-id must not appear with --resume)
          assert.ok(
            !spec.argv.includes('--session-id'),
            `--session-id should not appear in resume for ${harness}/${model}`
          );
        }
      });
    }
  }

  // Codex models with separate reasoning param (oompa style)
  const CODEX_BASE_MODELS = [
    'gpt-5.6-sol',
    'gpt-5.6-terra',
    'gpt-5.6-luna',
    'gpt-5.5',
    'gpt-5.3-codex',
    'gpt-5.3-codex-spark',
  ];
  const REASONING_LEVELS = ['minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra'];

  for (const model of CODEX_BASE_MODELS) {
    for (const reasoning of REASONING_LEVELS) {
      it(`codex/${model} + reasoning=${reasoning}: adds effort flag`, () => {
        const spec = buildCommand('codex', {
          model,
          prompt: 'test',
          reasoning,
        });
        assert.ok(
          spec.argv.includes(`model_reasoning_effort=${reasoning}`),
          `missing model_reasoning_effort=${reasoning} for ${model}: ${JSON.stringify(spec.argv)}`
        );
      });
    }
  }
});

