              event.type === 'text.delta'
          )
          .map((event) => event.text)
          .join('');
        assert.match(finalText, /\bSUBAGENTS_OK\b/);
      } finally {
        rmSync(tempRoot, { recursive: true, force: true });
      }
    }
  );
});

