// Claude shim for fork contract tests. Emits a claude-shaped init event
// and records its argv to a side-channel file keyed by the value of the
// CLAUDE_SHIM_LABEL env var (tests set this per-invocation so concurrent
// runs don't clobber each other's log).
function writeClaudeShim(binDir: string, logDir: string): void {
  const shimPath = path.join(binDir, 'claude');
  const shimSource = `#!/usr/bin/env node
const fs = require('node:fs');
const path = require('node:path');
const argv = process.argv.slice(2);
const label = process.env.CLAUDE_SHIM_LABEL || 'default';
const logPath = path.join(${JSON.stringify(logDir)}, 'claude-argv-' + label + '.json');
fs.writeFileSync(logPath, JSON.stringify(argv));
const emit = (obj) => process.stdout.write(JSON.stringify(obj) + '\\n');
emit({ type: 'system', subtype: 'init', session_id: 'forked-new-session-id', cwd: process.cwd(), model: 'claude-opus-4' });
emit({ type: 'assistant', message: { content: [{ type: 'text', text: 'hello from fork' }] } });
emit({ type: 'result', subtype: 'success' });
process.exit(0);
`;
  writeFileSync(shimPath, shimSource);
  chmodSync(shimPath, 0o755);
}

function writeGeminiShim(binDir: string): void {
  const shimPath = path.join(binDir, 'gemini2');
  const shimSource = `#!/usr/bin/env node
const promptIdx = process.argv.indexOf('-p');
const prompt = promptIdx >= 0 ? (process.argv[promptIdx + 1] ?? '') : '';
const resumeIdx = process.argv.indexOf('--resume');
const resumeSession = resumeIdx >= 0 ? (process.argv[resumeIdx + 1] ?? '') : '';
const emit = (obj) => process.stdout.write(JSON.stringify(obj) + '\\n');

if (prompt === 'gemini-auth-required') {
  process.stdout.write('Opening authentication page in your browser. Do you want to continue? [Y/n]:');
  process.exit(0);
}

if (prompt === 'gemini-success') {
  emit({ type: 'init', session_id: 'gemini-session-1' });
  emit({ type: 'tool_result', status: 'success', output: 'ls output' });
  emit({ type: 'message', role: 'assistant', content: 'hi from gemini' });
  emit({ type: 'result', status: 'success' });
  process.exit(0);
}

if (prompt === 'gemini-resume-success') {
  if (resumeSession !== 'gemini-session-1') {
    process.stderr.write('Use --list-sessions to see available sessions, then use --resume {number}, --resume {uuid}, or --resume latest.\\n');
    process.exit(3);
  }
  emit({ type: 'init', session_id: 'gemini-session-1' });
  emit({ type: 'message', role: 'assistant', content: 'hi again from gemini' });
  emit({ type: 'result', status: 'success' });
  process.exit(0);
}

process.exit(0);
`;

  writeFileSync(shimPath, shimSource);
  chmodSync(shimPath, 0o755);
}

function writeCursorShim(binDir: string): void {
  // Provide both `agent` (new) and `cursor-agent` (legacy fallback) shims
  // so resolveBinary fallback `agent` → `cursor-agent` and process-runner
  // effectiveBin logic can be exercised. Both shims share identical source.
  const shimSource = `#!/usr/bin/env node
const args = process.argv.slice(2);
const prompt = args[args.length - 1] ?? '';
const resumeIdx = args.indexOf('--resume');
const resumeSession = resumeIdx >= 0 ? (args[resumeIdx + 1] ?? '') : '';
const modelIdx = args.indexOf('--model');
const model = modelIdx >= 0 ? (args[modelIdx + 1] ?? '') : '';
const emit = (obj) => process.stdout.write(JSON.stringify(obj) + '\\n');

if (prompt === 'cursor-auth-required') {
  process.stdout.write('\\u001b[38;2;48;48;48m           +i":;;                     \\u001b[39m\\n');
  process.stdout.write('\\u001b[1mCursor Agent\\u001b[22m\\n');
  process.stdout.write('\\u001b[32mPress any key to sign in...\\u001b[39m\\n');
  process.exit(1);
}

if (prompt === 'cursor-success') {
  if (model !== 'composer-2.5') {
    process.stderr.write('unexpected model: ' + model + '\\n');
    process.exit(2);
  }
  emit({ type: 'system', subtype: 'init', session_id: 'cursor-session-1', model: 'Composer 2.5', permissionMode: 'default' });
  emit({ type: 'user', message: { role: 'user', content: [{ type: 'text', text: 'cursor-success' }] }, session_id: 'cursor-session-1' });
  emit({ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi from cursor' }] }, session_id: 'cursor-session-1', timestamp_ms: 1 });
  emit({ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi from cursor' }] }, session_id: 'cursor-session-1' });
  emit({ type: 'tool_call', subtype: 'started', call_id: 'tool_1', tool_call: { globToolCall: { args: { targetDirectory: '/tmp', globPattern: '*.ts' } } }, session_id: 'cursor-session-1' });
  emit({ type: 'tool_call', subtype: 'completed', call_id: 'tool_1', tool_call: { globToolCall: { args: { targetDirectory: '/tmp', globPattern: '*.ts' }, result: { success: { files: ['a.ts'], totalFiles: 1 } } } }, session_id: 'cursor-session-1' });
  emit({ type: 'result', subtype: 'success', is_error: false, result: 'hi from cursor', session_id: 'cursor-session-1' });
  process.exit(0);
}

if (prompt === 'cursor-resume-success') {
  if (resumeSession !== 'cursor-session-1') {
    process.stderr.write('resume mismatch: ' + resumeSession + '\\n');
    process.exit(3);
  }
  emit({ type: 'system', subtype: 'init', session_id: 'cursor-session-1', model: 'Composer 2.5', permissionMode: 'default' });
  emit({ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi again from cursor' }] }, session_id: 'cursor-session-1', timestamp_ms: 2 });
  emit({ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi again from cursor' }] }, session_id: 'cursor-session-1' });
  emit({ type: 'result', subtype: 'success', is_error: false, result: 'hi again from cursor', session_id: 'cursor-session-1' });
  process.exit(0);
}

process.exit(0);
`;

  for (const name of ['agent', 'cursor-agent']) {
    const shimPath = path.join(binDir, name);
    writeFileSync(shimPath, shimSource);
    chmodSync(shimPath, 0o755);
  }
}

async function collectEvents(
  events: AsyncIterable<UnifiedAgentEvent>
): Promise<UnifiedAgentEvent[]> {
  const out: UnifiedAgentEvent[] = [];
  for await (const event of events) {
    out.push(event);
  }
  return out;
}

